TEXT_OUTPUTS = {
    "tests/test_promotion_v4.py": "\"\"\"Generated synthetic regressions for Promotion4. Reproduce with tools/make_fixtures.py.\"\"\"\nimport copy\nimport datetime\nimport hashlib\nimport itertools\nimport json\nimport os\nfrom concurrent.futures import ThreadPoolExecutor\nfrom pathlib import Path\nimport subprocess\nimport threading\n\nimport pytest\n\nfrom scripts import (bandit, capabilities, dispatch, email_contract, events, learning,\n                     orchestrate, participation, private_storage, providers, runs, seqtest, throttle)\nfrom test_review_runs import SAMPLE, case, execute, live, authorized, ack\n\n\ndef test_tagged_case_sensitive_transport_address_is_preserved(case):\n    selected = 'User1+Selected@example.com'\n    case['audiences']['segments']['sample'][0]['recipient'] = selected\n    (case['root']/'audiences.json').write_text(json.dumps(case['audiences']))\n    result = execute(case)\n    payload = result['items'][0]['payload']\n    assert result['status'] == 'simulated'\n    assert payload['recipient'] == payload['destination'] == selected\n    assert payload['suppression_key'] == 'user1@example.com'\n    assert payload['audience_metadata']['recipient'] == selected\n    stored = json.loads((case['root']/'metrics/runs'/(result['run_id']+'.json')).read_text())\n    assert stored['items'][0]['payload']['recipient'] == selected\n\n\ndef test_alias_suppression_still_blocks_selected_transport(case, monkeypatch):\n    case['audiences']['segments']['sample'][0]['recipient'] = 'User1+Selected@example.com'\n    (case['root']/'audiences.json').write_text(json.dumps(case['audiences']))\n    (case['root']/'metrics/suppression.csv').write_text('USER1+blocked@example.com\\n')\n    calls = live(case, monkeypatch)\n    result = authorized(case)\n    assert result['counts'] == {'blocked': 1, 'complete': 1}\n    assert len(calls) == 1 and calls[0]['recipient'] == 'user2@example.com'\n\n\ndef email_fixture():\n    return copy.deepcopy(SAMPLE['email_payload'])\n\n\ndef wire_helper(case, monkeypatch, responder):\n    helper = case['root']/'synthetic-mail.ps1'\n    helper.write_text('# synthetic helper seam')\n    monkeypatch.setattr(providers, 'SEND_GMAIL_PS1', helper)\n    calls = []\n    def process(argv, **kwargs):\n        request = json.loads(argv[argv.index('-RequestJson')+1])\n        calls.append(request)\n        return subprocess.CompletedProcess(argv, 0, json.dumps(responder(request)), '')\n    monkeypatch.setattr(providers.subprocess, 'run', process)\n    return calls\n\n\ndef helper_receipt(request):\n    return {field: request[field] for field in\n            ('contract', 'platform', 'idempotency_key', 'destination', 'recipient', 'sender', 'request_sha256')} | {\n                'status': 'sent', 'message_id': 'synthetic-remote-id'}\n\n\ndef test_email_helper_receives_complete_frozen_request(case, monkeypatch):\n    calls = wire_helper(case, monkeypatch, helper_receipt)\n    payload = email_fixture()\n    payload['recipient'] = payload['destination'] = 'User1+Selected@example.com'\n    result = providers.EmailProvider().publish(payload, live=True)\n    assert dispatch.matching_receipt(result, payload)\n    request = calls[0]\n    assert request['recipient'] == 'User1+Selected@example.com'\n    assert request['sender'] == payload['from_addr'] and request['subject'] == payload['subject']\n    assert request['body'] == '\\n\\n'.join(payload[field] for field in\n                                         ('body', 'cta', 'physical_address', 'unsubscribe'))\n    unsigned = {key: value for key, value in request.items() if key != 'request_sha256'}\n    assert request['request_sha256'] == hashlib.sha256(json.dumps(\n        unsigned, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()).hexdigest()\n\n\n@pytest.mark.parametrize('field', ['contract', 'platform', 'idempotency_key', 'destination',\n                                  'recipient', 'sender', 'request_sha256', 'message_id'])\n@pytest.mark.parametrize('mutation', ['missing', 'wrong'])\ndef test_email_receipt_must_prove_each_required_field(case, monkeypatch, field, mutation):\n    def response(request):\n        result = helper_receipt(request)\n        if mutation == 'missing':\n            result.pop(field)\n        else:\n            result[field] = '' if field == 'message_id' else 'synthetic-wrong'\n        return result\n    calls = wire_helper(case, monkeypatch, response)\n    result = providers.EmailProvider().publish(email_fixture(), live=True)\n    assert result['status'] == 'uncertain' and len(calls) == 1\n    assert not dispatch.matching_receipt(result, email_fixture())\n\n\ndef test_unconfigured_email_contract_is_proven_not_applied(case, monkeypatch):\n    calls = wire_helper(case, monkeypatch, helper_receipt)\n    payload = email_fixture()\n    payload.pop('email_helper_contract')\n    result = providers.EmailProvider().publish(payload, live=True)\n    assert dispatch.matching_receipt(result, payload, 'not_applied') and calls == []\n    assert 'reviewed-email-v1' in result['reason']\n\n\n@pytest.mark.parametrize('field', ['body', 'cta', 'physical_address', 'unsubscribe'])\ndef test_changed_email_rendering_is_not_sent(case, monkeypatch, field):\n    calls = wire_helper(case, monkeypatch, helper_receipt)\n    payload = email_fixture()\n    payload[field] += ' synthetic changed value'\n    result = providers.EmailProvider().publish(payload, live=True)\n    assert dispatch.matching_receipt(result, payload, 'not_applied') and calls == []\n\n\n@pytest.mark.parametrize('platform', ['email', 'discord', 'mastodon', 'bluesky'])\ndef test_missing_provider_setup_is_retryable_without_publication(case, monkeypatch, platform):\n    payload = {**email_fixture(), 'platform': platform}\n    for key in SAMPLE['credentials']:\n        monkeypatch.delenv(key, raising=False)\n    monkeypatch.setattr(providers, 'SEND_GMAIL_PS1', case['root']/'absent-helper')\n    def effect(*args, **kwargs):\n        pytest.fail('known setup failure must not publish')\n    monkeypatch.setattr(providers.subprocess, 'run', effect)\n    monkeypatch.setattr(providers.urllib.request, 'urlopen', effect)\n    result = providers.get(platform).publish(payload, live=True)\n    assert dispatch.matching_receipt(result, payload, 'not_applied')\n\n\ndef test_missing_email_helper_can_retry_exact_saved_action(case, monkeypatch):\n    case['cfg'].product['send_mode'] = 'live'\n    monkeypatch.setattr(providers, 'SEND_GMAIL_PS1', case['root']/'absent-helper')\n    first = authorized(case)\n    assert first['status'] == 'failed' and all(item['safe_to_retry'] for item in first['items'])\n    keys = [item['idempotency_key'] for item in first['items']]\n    calls = wire_helper(case, monkeypatch, helper_receipt)\n    second = authorized(case, resume=True)\n    assert second['status'] == 'complete'\n    assert [payload['idempotency_key'] for payload in calls] == keys\n\n\ndef remote_metadata(remotes, visibility):\n    calls = []\n    def metadata(argv):\n        calls.append(argv)\n        if argv[0] == 'gh':\n            identity = argv[3]\n            value = visibility.get(identity)\n            return json.dumps({'visibility': value, 'nameWithOwner': identity}) if value else '{}'\n        if argv[-1:] == ['remote']:\n            return '\\n'.join(remotes)\n        if argv[-3:] == ['rev-parse', '--verify', 'HEAD']:\n            return '1'*40\n        if 'get-url' in argv and '--all' in argv:\n            remote = argv[-1]\n            return '\\n'.join(remotes[remote]['push' if '--push' in argv else 'fetch'])\n        raise AssertionError('unexpected synthetic metadata operation')\n    return metadata, calls\n\n\n@pytest.mark.parametrize('placement', ['origin-push', 'second-fetch', 'second-push'])\n@pytest.mark.parametrize('visibility', ['PUBLIC', 'UNKNOWN', None])\ndef test_every_effective_remote_endpoint_must_be_private(case, monkeypatch, placement, visibility):\n    primary = 'https://github.com/example/synthetic-promotion-config.git'\n    other = 'https://github.com/example/synthetic-secondary.git'\n    remotes = {'origin': {'fetch': [primary], 'push': [primary]}}\n    if placement == 'origin-push':\n        remotes['origin']['push'].append(other)\n    else:\n        remotes['secondary'] = {'fetch': [primary], 'push': [primary]}\n        remotes['secondary']['fetch' if placement == 'second-fetch' else 'push'] = [other]\n    metadata, calls = remote_metadata(remotes, {'example/synthetic-promotion-config': 'PRIVATE',\n                                                'example/synthetic-secondary': visibility})\n    monkeypatch.setattr(private_storage, '_run', metadata)\n    with pytest.raises(ValueError, match='PUBLIC or unknown'):\n        private_storage.prove(case['root']/'metrics/state.json')\n    assert any(argv[0] == 'gh' and argv[3] == 'example/synthetic-secondary' for argv in calls)\n\n\ndef test_private_proof_names_all_accepted_destinations_and_is_fresh(case, monkeypatch):\n    primary = 'https://github.com/example/synthetic-promotion-config.git'\n    remotes = {'origin': {'fetch': [primary], 'push': [primary]}}\n    visibility = {'example/synthetic-promotion-config': 'PRIVATE'}\n    metadata, calls = remote_metadata(remotes, visibility)\n    monkeypatch.setattr(private_storage, '_run', metadata)\n    accepted = private_storage.publication_destinations(case['root'])\n    assert accepted == (('origin', 'fetch', 'example/synthetic-promotion-config'),\n                        ('origin', 'push', 'example/synthetic-promotion-config'))\n    path = case['root']/'metrics/events.jsonl'\n    events.append(path, events.make_event('synthetic', 'drafted'))\n    previous = path.read_bytes()\n    visibility['example/synthetic-promotion-config'] = 'PUBLIC'\n    with pytest.raises(ValueError):\n        events.append(path, events.make_event('synthetic', 'drafted'))\n    assert path.read_bytes() == previous\n\n\n@pytest.mark.parametrize('url', ['https://example.com/owner/repo', 'file:///synthetic',\n                                 'https://user@example.com/owner/repo', 'ssh://git@github.com:22/owner/repo'])\ndef test_unverifiable_remote_url_is_refused(url):\n    with pytest.raises(ValueError):\n        private_storage._remote_identity(url)\n\n\ndef reserve(thr, key, *, policy=None, payload=None, action='post'):\n    return thr.reserve('synthetic-account', 'email', action, policy or {'day_cap': 1, 'min_gap_sec': 0},\n                       reservation_id=key, payload=payload or {'body': 'synthetic'})\n\n\ndef test_two_preloaded_writers_cannot_overspend_shared_cap(case):\n    path = case['root']/'metrics/throttle-state.json'\n    first, second = [throttle.Throttle(path, clock=lambda: 1000) for _ in range(2)]\n    barrier = threading.Barrier(2)\n    def attempt(pair):\n        instance, key = pair\n        barrier.wait(timeout=5)\n        return reserve(instance, key)[0]\n    with ThreadPoolExecutor(max_workers=2) as pool:\n        results = list(pool.map(attempt, [(first, 'synthetic-a'), (second, 'synthetic-b')]))\n    assert sum(results) == 1\n    saved = json.loads(path.read_text())\n    assert len(saved['reservations']) == 1\n    assert next(iter(saved['buckets'].values()))['tokens'] == 0\n\n\ndef test_reservation_survives_lost_process_and_reuses_only_same_intent(case):\n    path = case['root']/'metrics/throttle-state.json'\n    assert reserve(throttle.Throttle(path, clock=lambda: 1000), 'synthetic-a')[0]\n    restarted = throttle.Throttle(path, clock=lambda: 1001)\n    assert not reserve(restarted, 'synthetic-b')[0]\n    assert reserve(restarted, 'synthetic-a')[0]\n    with pytest.raises(ValueError, match='collides'):\n        reserve(restarted, 'synthetic-a', payload={'body': 'changed synthetic intent'})\n    with pytest.raises(ValueError, match='collides'):\n        reserve(restarted, 'synthetic-a', action='dm')\n\n\n@pytest.mark.parametrize('malformed', ['', '{', '[]', '{\"schema_version\":true}', '{\"bucket\":{}}'])\ndef test_malformed_throttle_never_resets_capacity(case, malformed):\n    path = case['root']/'metrics/throttle-state.json'\n    path.write_text(malformed)\n    with pytest.raises(ValueError):\n        throttle.Throttle(path, clock=lambda: 1000)\n    assert path.read_text() == malformed\n\n\ndef test_old_reservation_cannot_skip_new_period_cap(case):\n    now = [1000]\n    instance = throttle.Throttle(case['root']/'metrics/throttle-state.json', clock=lambda: now[0])\n    assert reserve(instance, 'synthetic-a')[0]\n    now[0] += 86401\n    assert reserve(instance, 'synthetic-b')[0]\n    assert not reserve(instance, 'synthetic-a')[0]\n\n\ndef test_same_reservation_obeys_current_pacing_and_account_cooldown(case):\n    now = [1000]\n    instance = throttle.Throttle(case['root']/'metrics/throttle-state.json', clock=lambda: now[0])\n    policy = {'day_cap': 2, 'min_gap_sec': 100, 'backoff': {'factor': 0.5, 'cooldown_h': 1}}\n    assert reserve(instance, 'synthetic-a', policy=policy)[0]\n    assert not reserve(instance, 'synthetic-a', policy=policy)[0]\n    instance.record_throttle_signal('synthetic-account', 'email', 'post', policy)\n    restarted = throttle.Throttle(instance.path, clock=lambda: now[0]+200)\n    assert not reserve(restarted, 'synthetic-a', policy=policy)[0]\n    assert not reserve(restarted, 'synthetic-dm', policy=policy, action='dm')[0]\n\n\ndef test_429_persists_cooldown_before_next_item_and_next_run(case, monkeypatch):\n    calls = live(case, monkeypatch, lambda payload, count: {\n        'status': 'throttled', 'rate_limited': True, 'reason': 'synthetic 429'})\n    first = authorized(case)\n    assert first['counts'] == {'uncertain': 1, 'deferred': 1} and len(calls) == 1\n    saved = json.loads((case['root']/'metrics/throttle-state.json').read_text())\n    assert saved['cooldowns'] and not first['items'][0]['safe_to_retry']\n    second = orchestrate.run_once(case['cfg'], case['campaign'], run_id='synthetic-next',\n                                 env={'PROMO_LIVE_AUTHORIZED_EMAIL': 'synthetic-token'})\n    assert second['counts'] == {'deferred': 2} and len(calls) == 1\n\n\ndef test_cooldown_persistence_failure_stops_remaining_effects(case, monkeypatch):\n    calls = live(case, monkeypatch, lambda payload, count: {\n        'status': 'throttled', 'rate_limited': True, 'reason': 'synthetic 429'})\n    def failed(*args, **kwargs):\n        raise OSError('synthetic cooldown write failure')\n    monkeypatch.setattr(throttle.Throttle, 'record_throttle_signal', failed)\n    result = authorized(case)\n    assert result['status'] == 'uncertain' and len(calls) == 1\n    saved = json.loads((case['root']/'metrics/runs'/(case['run_id']+'.json')).read_text())\n    assert saved['items'][0]['status'] == 'uncertain' and saved['items'][1]['status'] == 'pending'\n\n\ndef test_complete_resume_does_not_recredit_and_delayed_event_credits_once(case, monkeypatch):\n    calls = live(case, monkeypatch)\n    first = authorized(case)\n    path = case['root']/'metrics/bandit-state.json'\n    baseline = path.read_bytes()\n    assert authorized(case, resume=True)['reward_status'] == 'no-new-observations'\n    assert path.read_bytes() == baseline and len(calls) == 2\n    decision = first['items'][0]['idempotency_key']\n    ev = events.make_event('email', 'conversion', arm_id=first['arm'], decision_id=decision)\n    events.append(case['root']/'metrics/events.jsonl', ev)\n    assert authorized(case, resume=True)['reward_status'] == 'ok'\n    updated = path.read_bytes()\n    assert updated != baseline\n    assert authorized(case, resume=True)['reward_status'] == 'no-new-observations'\n    assert path.read_bytes() == updated\n    assert json.loads(updated)['arms'][first['arm']]['n_pulls'] == 3\n\n\ndef test_unrelated_arm_history_is_not_credited_to_this_run(case, monkeypatch):\n    events.append(case['root']/'metrics/events.jsonl', events.make_event(\n        'email', 'conversion', arm_id=SAMPLE['arms'][0]['id'], decision_id='synthetic-other-decision'))\n    live(case, monkeypatch)\n    result = authorized(case)\n    saved = json.loads((case['root']/'metrics/bandit-state.json').read_text())\n    assert saved['arms'][result['arm']]['n_pulls'] == 2\n    assert all(credit['decision_id'] != 'synthetic-other-decision'\n               for credit in saved['observation_credits'].values())\n\n\ndef test_censored_event_waits_for_new_linked_evidence(case):\n    path = case['root']/'metrics/bandit-state.json'\n    row = events.make_event('email', 'sent', arm_id='synthetic-arm', decision_id='synthetic-decision',\n                            ts=1000, propensity_p=1.0, policy_version='synthetic')\n    args = {'arm_id': 'synthetic-arm', 'decision_ids': ['synthetic-decision'], 'conversion_window_s': 100}\n    assert learning.credit_observations(path, [row], now=1001, **args) == (None, 'censored')\n    baseline = path.read_bytes()\n    assert learning.credit_observations(path, [row], now=1200, **args) == (None, 'no-new-observations')\n    assert path.read_bytes() == baseline\n    conversion = events.make_event('email', 'conversion', arm_id='synthetic-arm',\n                                   decision_id='synthetic-decision', ts=1200)\n    assert learning.credit_observations(path, [row, conversion], now=1200, **args)[1] == 'ok'\n    assert json.loads(path.read_text())['arms']['synthetic-arm']['n_pulls'] == 1\n\n\ndef test_legacy_posterior_baselines_history_without_recredit(case):\n    path = case['root']/'metrics/bandit-state.json'\n    legacy = {'policy_version': 'synthetic', 'arms': {\n        'synthetic-arm': {'arm_id': 'synthetic-arm', 'alpha': 3.0, 'beta': 2.0, 'n_pulls': 3}}}\n    path.write_text(json.dumps(legacy))\n    row = events.make_event('email', 'conversion', arm_id='synthetic-arm', decision_id='synthetic-decision')\n    result = learning.credit_observations(path, [row], arm_id='synthetic-arm', decision_ids=['synthetic-decision'])\n    assert result == (None, 'legacy-baseline-established')\n    saved = json.loads(path.read_text())\n    assert saved['arms'] == legacy['arms']\n    assert saved['observation_credits'][row['event_id']]['status'] == 'legacy-observed'\n\n\ndef test_reused_observation_id_with_changed_content_is_rejected(case):\n    path = case['root']/'metrics/bandit-state.json'\n    row = events.make_event('email', 'conversion', arm_id='synthetic-arm', decision_id='synthetic-decision')\n    args = {'arm_id': 'synthetic-arm', 'decision_ids': ['synthetic-decision']}\n    learning.credit_observations(path, [row], **args)\n    before = path.read_bytes()\n    with pytest.raises(ValueError, match='identity changed'):\n        learning.credit_observations(path, [{**row, 'value': 2.0}], **args)\n    assert path.read_bytes() == before\n\n\ndef test_manual_arm_choice_has_truthful_human_provenance_and_deduplicates(case):\n    args = {'channel': 'synthetic-manual', 'url': 'https://example.com/posts/synthetic',\n            'arm_id': 'synthetic-arm', 'campaign': 'synthetic-campaign'}\n    first = orchestrate.record_post(case['cfg'], **args)\n    second = orchestrate.record_post(case['cfg'], **args)\n    assert first['status'] == second['status'] == 'recorded' and first['event_id'] == second['event_id']\n    row = events.read(case['root']/'metrics/events.jsonl')[0]\n    assert row['decision_origin'] == row['actuator'] == 'human'\n    assert row['propensity_p'] is None and row['policy_version'] is None\n    assert events.validate_event(row) == []\n    assert events.validate_event({**row, 'propensity_p': 0.5})\n    assert orchestrate.record_post(case['cfg'], **{**args, 'arm_id': 'other-arm'})['status'] == 'error'\n\n\ndef manual_case(case):\n    case['cfg'].registry['channels'][0].update(slug='synthetic-manual', platform='reddit', transport='post')\n    case['arms'][0]['channel'] = 'synthetic-manual'\n    (case['root']/'copy'/(case['campaign']+'.json')).write_text(json.dumps(case['arms']))\n    return case\n\n\ndef test_prepared_choice_retains_real_probability(case):\n    manual_case(case)\n    result = orchestrate.prep_once(case['cfg'], case['campaign'])\n    assert result['status'] == 'prepared'\n    recorded = orchestrate.record_post(case['cfg'], 'synthetic-manual', 'https://example.com/posts/synthetic',\n                                        decision_id=result['decision_id'])\n    assert recorded['status'] == 'recorded'\n    rows = events.read(case['root']/'metrics/events.jsonl')\n    assert rows[-1]['decision_origin'] == 'bandit'\n    assert rows[-1]['propensity_p'] == rows[0]['propensity_p'] > 0\n    assert rows[-1]['policy_version'] == rows[0]['policy_version']\n\n\ndef test_manual_prep_checks_actual_copy_before_prepared_event(case):\n    manual_case(case)\n    case['arms'][0]['body'] = 'Synthetic copy with unlimited free promises'\n    (case['root']/'copy'/(case['campaign']+'.json')).write_text(json.dumps(case['arms']))\n    result = orchestrate.prep_once(case['cfg'], case['campaign'])\n    assert result['status'] == 'blocked' and result['reasons']\n    assert events.read(case['root']/'metrics/events.jsonl') == []\n\n\ndef test_participation_requires_explicit_thread_draft_and_final_type(case):\n    path = case['root']/'metrics/events.jsonl'\n    first_thread = 'https://www.reddit.com/r/synthetic/comments/abc/topic'\n    second_thread = 'https://www.reddit.com/r/synthetic/comments/def/other'\n    first = events.make_event('reddit-participation', 'drafted', platform='reddit',\n                              thread=participation.thread_identity(first_thread), graduated=True,\n                              compliance_ok=True, utm={'content': 'synthetic-aff'})\n    later = events.make_event('reddit-participation', 'drafted', platform='reddit',\n                              thread=participation.thread_identity(second_thread), graduated=False)\n    for row in [first, later]:\n        events.append(path, row)\n    assert participation.confirmed_entries(events.read(path)) == []\n    kwargs = {'thread': first_thread, 'draft_id': first['event_id'], 'participation_type': 'ask'}\n    url = first_thread+'/xyz'\n    result = orchestrate.record_participation(case['cfg'], url, **kwargs)\n    assert result['status'] == 'recorded' and result['linked_draft'] == first['event_id']\n    repeated = orchestrate.record_participation(case['cfg'], url+'?utm_source=synthetic', **kwargs)\n    assert repeated['event_id'] == result['event_id']\n    rows = events.read(path)\n    assert rows[-1]['graduated'] is True and rows[-1]['participation_type'] == 'ask'\n    ledger = participation.ledger_balance(participation.confirmed_entries(rows))\n    assert ledger['gives'] == 0 and ledger['asks'] == 1\n    assert orchestrate.record_participation(case['cfg'], url, **{**kwargs, 'draft_id': later['event_id']})['status'] == 'error'\n    assert orchestrate.record_participation(case['cfg'], url, **{**kwargs, 'participation_type': 'give'})['status'] == 'error'\n    assert orchestrate.record_participation(case['cfg'], url, thread=first_thread)['status'] == 'error'\n\n\n@pytest.mark.parametrize('alpha', [0.05, 0.2, 0.5])\ndef test_two_sided_p_agrees_with_crossing_and_finite_null_peeking(alpha):\n    rejected = 0\n    horizon = 10\n    for signs in itertools.product((0, 1), repeat=horizon):\n        test = seqtest.SequentialABTest(alpha=alpha)\n        prior = 1.0\n        for sign in signs:\n            snapshot = test.update(sign, 1-sign)\n            assert snapshot['p_value'] == min(1.0, 2.0/snapshot['max_one_sided_wealth'])\n            assert snapshot['p_value'] <= prior\n            assert (snapshot['p_value'] <= alpha) == snapshot['reject']\n            prior = snapshot['p_value']\n        rejected += test.reject\n    # Exact enumeration of the independent, conditionally symmetric paired-sign null.\n    assert rejected/(2**horizon) <= alpha\n\n\ndef test_schedule_keys_include_obligation_and_respect_horizon(case):\n    class Bridge:\n        def __init__(self):\n            self.calls = []\n        def available(self):\n            return True\n        def schedule_item(self, **kwargs):\n            self.calls.append(kwargs)\n            return {'ok': True, 'item': {'id': kwargs['idempotency_key']}}\n    arms = [{**SAMPLE['arms'][0], 'id': 'synthetic-arm-'+str(index)} for index in range(3)]\n    (case['root']/'copy'/(case['campaign']+'.json')).write_text(json.dumps(arms))\n    (case['root']/'channels/email/policy.json').write_text(json.dumps({'min_gap_sec': 172800}))\n    start = datetime.datetime(2026, 1, 1)\n    short, long = Bridge(), Bridge()\n    assert orchestrate.plan(case['cfg'], case['campaign'], start=start, days=1, bridge=short)['scheduled'] == 1\n    assert orchestrate.plan(case['cfg'], case['campaign'], start=start, days=5, bridge=long)['scheduled'] == 3\n    assert short.calls[0]['idempotency_key'] == long.calls[0]['idempotency_key']\n    alternate = 'synthetic-other-campaign'\n    (case['root']/'copy'/(alternate+'.json')).write_text(json.dumps(arms))\n    changed = Bridge()\n    orchestrate.plan(case['cfg'], alternate, start=start, days=1, bridge=changed)\n    assert changed.calls[0]['idempotency_key'] != short.calls[0]['idempotency_key']\n    case['cfg'].registry['channels'][0]['account_handle'] = 'synthetic-other-account'\n    account = Bridge()\n    orchestrate.plan(case['cfg'], case['campaign'], start=start, days=1, bridge=account)\n    assert account.calls[0]['idempotency_key'] != short.calls[0]['idempotency_key']\n    with pytest.raises(ValueError):\n        orchestrate.plan(case['cfg'], case['campaign'], days=0, bridge=Bridge())\n\n\ndef test_email_resource_without_reviewed_contract_is_not_ready(case, monkeypatch):\n    helper = case['root']/'synthetic-helper.ps1'\n    helper.write_text('# synthetic')\n    case['cfg'].registry['channels'][0].pop('email_helper_contract')\n    result = capabilities.doctor(case['cfg'], env={'PROMO_SEND_GMAIL': str(helper)})\n    assert result['status'] == 'not_ready'\n    assert not result['channels'][0]['configured'] and result['live_proven'] == 'not_run'\n\n\n@pytest.mark.parametrize('name', ['events.jsonl', 'throttle-state.json', 'bandit-state.json', 'synthetic-run.json'])\ndef test_existing_output_hardlinks_are_refused(case, name):\n    source = case['root']/'synthetic-original.txt'\n    source.write_text('synthetic retained content')\n    target = case['root']/'metrics'/name\n    os.link(source, target)\n    assert target.stat().st_nlink == 2\n    with pytest.raises(ValueError, match='hardlink'):\n        private_storage.prove(target)\n    assert source.read_text() == target.read_text() == 'synthetic retained content'\n\n\ndef test_repeated_same_dispatch_outcome_has_one_observation_identity(case, monkeypatch):\n    (case['root']/'metrics/suppression.csv').write_text('user1@example.com\\nuser2@example.com\\n')\n    live(case, monkeypatch)\n    first = authorized(case)\n    assert first['counts'] == {'blocked': 2}\n    path = case['root']/'metrics/bandit-state.json'\n    before = path.read_bytes()\n    assert authorized(case, resume=True)['reward_status'] == 'no-new-observations'\n    assert path.read_bytes() == before\n    rows = events.read(case['root']/'metrics/events.jsonl')\n    assert len(rows) == 2 and len({row['event_id'] for row in rows}) == 2\n\n\ndef test_throttle_semantically_corrupt_capacity_is_not_accepted(case):\n    path = case['root']/'metrics/throttle-state.json'\n    instance = throttle.Throttle(path, clock=lambda: 1000)\n    assert reserve(instance, 'synthetic-a')[0]\n    document = json.loads(path.read_text())\n    next(iter(document['buckets'].values()))['tokens'] = 99\n    path.write_text(json.dumps(document))\n    before = path.read_bytes()\n    with pytest.raises(ValueError, match='exceed'):\n        throttle.Throttle(path, clock=lambda: 1001)\n    assert path.read_bytes() == before\n",
    "tests/conftest.py": "\"\"\"Pytest path setup so `from scripts import ...` resolves the skill engine.\n\nThe engine lives at skills/promotion-assistant/scripts (a `scripts` package). Putting\nskills/promotion-assistant on sys.path mirrors selftest.py's own bootstrap.\n\"\"\"\nimport pathlib\nimport sys\nimport builtins\nimport io\nimport os\nimport socket\nimport subprocess\nimport tempfile\nimport urllib.request\n\n# Install safety seams before importing the engine or collecting business tests.\nfor _key in list(os.environ):\n    if _key.startswith(('PROMO_', 'PROMOTION_ASSISTANT_')):\n        os.environ.pop(_key)\n\n\ndef _no_network(*args, **kwargs):\n    raise AssertionError('test attempted an unmocked network operation')\n\n\nsocket.socket.connect = _no_network\nsocket.create_connection = _no_network\nurllib.request.urlopen = _no_network\n_real_run = subprocess.run\n\n\ndef _safe_process(argv, *args, **kwargs):\n    if isinstance(argv, (list, tuple)) and argv[0] == 'git' and 'check-ignore' in argv:\n        return _real_run(argv, *args, **kwargs)\n    raise AssertionError('test attempted an unmocked external process')\n\n\nsubprocess.run = _safe_process\n_real_open = io.open\n_temporary = pathlib.Path(tempfile.gettempdir()).resolve()\n\n\ndef _safe_open(file, *args, **kwargs):\n    if isinstance(file, (str, os.PathLike)):\n        path = pathlib.Path(file).resolve()\n        if path.name in {'product.json', 'registry.json', 'audiences.json', 'consent-ledger.jsonl', 'suppression.csv'}:\n            if not path.is_relative_to(_temporary) and 'tests' not in path.parts:\n                raise AssertionError('test attempted real runtime data access')\n    return _real_open(file, *args, **kwargs)\n\n\nio.open = _safe_open\nbuiltins.open = _safe_open\n\n_ROOT = pathlib.Path(__file__).resolve().parent.parent\n_PKG = _ROOT / \"skills\" / \"promotion-assistant\"\nif str(_PKG) not in sys.path:\n    sys.path.insert(0, str(_PKG))\n\nimport pytest\n\n\n@pytest.fixture(autouse=True)\ndef synthetic_private_metadata(monkeypatch):\n    # The same controls also run against the immutable pre-change source.\n    import importlib.util\n    if importlib.util.find_spec('scripts.private_storage') is None:\n        return\n    from scripts import private_storage\n    actual_repository = private_storage.repository\n\n    def repository(existing):\n        if not existing.is_relative_to(_temporary):\n            raise ValueError('test destination must be synthetic temporary storage')\n        return next((node for node in (existing, *existing.parents)\n                     if (node/'product.json').is_file() or (node/'.git').exists()), existing)\n\n    def metadata(argv):\n        if argv[0] == 'git':\n            if argv[-1:] == ['remote']:\n                return 'origin'\n            if argv[-3:] == ['rev-parse', '--verify', 'HEAD']:\n                return '1'*40\n            if (('get-url' in argv and '--all' in argv and argv[-1] == 'origin')\n                    or argv[-3:] == ['remote', 'get-url', 'origin']):\n                return 'https://github.com/example/synthetic-promotion-config.git'\n            raise AssertionError('unexpected Git metadata query')\n        if argv[0] == 'gh' and argv[1:4] == ['repo', 'view', 'example/synthetic-promotion-config']:\n            return '{\"visibility\":\"PRIVATE\",\"nameWithOwner\":\"example/synthetic-promotion-config\"}'\n        raise AssertionError('unexpected metadata operation')\n\n    monkeypatch.setattr(private_storage, 'repository', repository)\n    monkeypatch.setattr(private_storage, '_run', metadata)\n    return actual_repository\n",
    "tests/test_review_runs.py": "\"\"\"Public generated controls, using only synthetic PRIVATE metadata and effect seams.\"\"\"\nimport copy\nimport json\nfrom pathlib import Path\nimport subprocess\n\nimport pytest\nfrom scripts import config, orchestrate, dispatch, providers, schedule_bridge, email_contract\n\nSAMPLE = json.loads((Path(__file__).parent/'fixtures/promotion.json').read_text())\n\n\n@pytest.fixture\ndef case(tmp_path, monkeypatch):\n    root = tmp_path/'companion'\n    root.mkdir()\n    (root/'.git').mkdir()\n    sample = copy.deepcopy(SAMPLE)\n    for folder in ('copy', 'channels/email', 'metrics', 'compliance'):\n        (root/folder).mkdir(parents=True, exist_ok=True)\n    paths = {'product.json': sample['product'], 'registry.json': sample['registry'],\n             'audiences.json': sample['audiences'],\n             'copy/'+sample['campaign']+'.json': sample['arms'],\n             'channels/email/policy.json': sample['policy']}\n    for name, value in paths.items():\n        (root/name).write_text(json.dumps(value), encoding='utf-8')\n    (root/'compliance/consent-ledger.jsonl').write_text(\n        ''.join(json.dumps(row)+'\\n' for row in sample['consent']), encoding='utf-8')\n\n    def process(argv, **kwargs):\n        if argv[0] == 'git':\n            if '--show-toplevel' in argv:\n                answer = str(root)\n            elif argv[-1:] == ['remote']:\n                answer = 'origin'\n            elif argv[-3:] == ['rev-parse', '--verify', 'HEAD']:\n                answer = '1'*40\n            elif 'get-url' in argv and '--all' in argv:\n                answer = sample['origin']\n            else:\n                raise AssertionError('unexpected Git metadata query')\n        elif argv[0] == 'gh':\n            answer = json.dumps({'visibility': 'PRIVATE', 'nameWithOwner': 'example/synthetic-promotion-config'})\n        else:\n            raise AssertionError('unexpected external process')\n        return subprocess.CompletedProcess(argv, 0, answer, '')\n\n    monkeypatch.setattr(subprocess, 'run', process)\n    sample.update(root=root, cfg=config.Config(root))\n    return sample\n\n\ndef execute(case, **kwargs):\n    return orchestrate.run_once(case['cfg'], case['campaign'], env={}, **kwargs)\n\n\ndef test_review_expands_full_payload_and_permission(case):\n    result = execute(case)\n    assert result['status'] == 'simulated' and result['counts']['simulated'] == 2\n    assert len(result['items']) == 2\n    for item in result['items']:\n        assert item['payload']['body'] == case['arms'][0]['body']\n        assert item['payload']['destination'] == item['payload']['recipient']\n        assert item['eligibility']['consent'] and item['eligibility']['suppressed'] is False\n    rows = [json.loads(line) for line in (case['root']/'metrics/dry-run.jsonl').read_text().splitlines()]\n    assert all(row['would_send']['body'] == case['arms'][0]['body'] for row in rows)\n\n\ndef test_withdrawal_overrides_old_and_retained_lawful_basis(case):\n    record = {**case['consent'][0], 'status': 'withdrawn'}\n    with (case['root']/'compliance/consent-ledger.jsonl').open('a') as stream:\n        stream.write(json.dumps(record)+'\\n')\n    result = execute(case)\n    assert result['status'] == 'partial' and result['counts']['blocked'] == 1\n    previews = [json.loads(row) for row in (case['root']/'metrics/dry-run.jsonl').read_text().splitlines()]\n    assert len(previews) == 2 and any(row['status'] == 'rejected' for row in previews)\n    assert all(row['payload']['body'] == case['arms'][0]['body'] for row in previews)\n\n\ndef test_missing_segment_is_visible_and_blocked(case):\n    (case['root']/'audiences.json').write_text('{}')\n    assert execute(case)['status'] == 'blocked'\n\n\n@pytest.mark.parametrize('recipient', SAMPLE['invalid_recipients'])\ndef test_blocked_recipient_input_survives_review_preview_and_history(case, recipient):\n    case['audiences']['segments']['sample'] = [\n        {'recipient': recipient, 'recipient_country': 'US'}]\n    (case['root']/'audiences.json').write_text(json.dumps(case['audiences']))\n    result = execute(case, run_id=case['run_id'])\n    assert result['status'] == 'blocked'\n    item = result['items'][0]\n    assert item['payload']['destination'] == ''\n    preview = json.loads((case['root']/'metrics/dry-run.jsonl').read_text().splitlines()[0])\n    saved = json.loads((case['root']/'metrics/runs'/(case['run_id']+'.json')).read_text())\n    for payload in (item['payload'], preview['payload'], saved['items'][0]['payload']):\n        assert payload['supplied_recipient'] == recipient\n        assert payload['idempotency_key'] == item['idempotency_key']\n\n\ndef test_distinct_blocked_inputs_keep_their_association_on_resume(case, monkeypatch):\n    recipients = case['invalid_recipients'][1:3]\n    case['audiences']['segments']['sample'] = [\n        {'recipient': recipient, 'recipient_country': 'US'} for recipient in recipients]\n    (case['root']/'audiences.json').write_text(json.dumps(case['audiences']))\n    calls = live(case, monkeypatch)\n    first = authorized(case)\n    assert first['counts'] == {'blocked': 2}\n    original_keys = [item['idempotency_key'] for item in first['items']]\n    assert len(set(original_keys)) == 2\n\n    (case['root']/'audiences.json').write_text('{}')\n    resumed = authorized(case, resume=True)\n    assert resumed['counts'] == {'blocked': 2} and calls == []\n    assert [item['idempotency_key'] for item in resumed['items']] == original_keys\n    assert [item['payload']['supplied_recipient']\n            for item in resumed['items']] == recipients\n\n\ndef test_equivalent_duplicates_collapse(case):\n    audiences = case['audiences']\n    audiences['segments']['sample'].append({'recipient': 'USER1+tag@example.com', 'recipient_country': 'us'})\n    (case['root']/'audiences.json').write_text(json.dumps(audiences))\n    result = execute(case)\n    assert len(result['items']) == 2 and result['duplicate_count'] == 1\n\n\ndef test_new_run_is_durable_and_existing_id_never_overwrites(case):\n    first = execute(case, run_id=case['run_id'])\n    path = case['root']/'metrics/runs'/(case['run_id']+'.json')\n    before = path.read_bytes()\n    assert first['run_id'] == case['run_id']\n    assert execute(case, run_id=case['run_id'])['status'] == 'failed'\n    assert path.read_bytes() == before\n\n\n@pytest.mark.parametrize('run_id', SAMPLE['invalid_runs'])\ndef test_invalid_run_identity_fails(case, run_id):\n    assert execute(case, run_id=run_id)['status'] in {'blocked', 'failed'}\n\n\ndef test_missing_prep_scope_never_falls_back(case):\n    assert orchestrate.prep_once(case['cfg'], case['campaign'], channel='absent')['status'] == 'blocked'\n\n\ndef test_explicit_missing_config_is_authoritative(case, monkeypatch):\n    monkeypatch.setenv('PROMO_CONFIG_DIR', str(case['root']))\n    with pytest.raises(config.ConfigError):\n        config.load(str(case['root']/'missing'))\n\n\ndef test_schedule_non_json_cannot_confirm(case, monkeypatch):\n    helper = case['root']/'synthetic-helper.py'\n    helper.write_text('# Synthetic helper')\n    monkeypatch.setattr(subprocess, 'run', lambda *a, **k: subprocess.CompletedProcess(a, 0, 'not JSON', ''))\n    result = schedule_bridge.ScheduleBridge(helper).schedule_item(\n        title='Synthetic task', due_at='2026-01-01T00:00:00Z', idempotency_key='synthetic', ext={})\n    assert result['ok'] is False\n\n\ndef live(case, monkeypatch, response=None):\n    case['cfg'].product['send_mode'] = 'live'\n    calls = []\n\n    class Adapter:\n        LIVE_TRANSPORT = True\n\n        def publish(self, payload, *, live=False):\n            calls.append(copy.deepcopy(payload))\n            if response:\n                return response(payload, len(calls))\n            return ack(payload)\n\n        dm = publish\n\n    monkeypatch.setattr(providers, 'get', lambda platform: Adapter())\n    return calls\n\n\ndef ack(payload, status='sent'):\n    envelope = email_contract.request(payload) if payload.get('platform') == 'email' else {}\n    return {**envelope, 'status': status, 'platform': payload['platform'],\n            'idempotency_key': payload['idempotency_key'], 'destination': payload['destination'],\n            'message_id': SAMPLE['message_id'], 'evidence': 'Synthetic provider proves no application',\n            'evidence_kind': 'synthetic'}\n\n\ndef authorized(case, **kwargs):\n    return orchestrate.run_once(case['cfg'], case['campaign'], run_id=case['run_id'],\n                               env={'PROMO_LIVE_AUTHORIZED_EMAIL': 'synthetic-token'}, **kwargs)\n\n\n@pytest.mark.parametrize('response', SAMPLE['invalid_ack'])\ndef test_ambiguous_acknowledgements_are_durable_uncertainty(case, monkeypatch, response):\n    calls = live(case, monkeypatch, lambda payload, count: response)\n    result = authorized(case)\n    assert result['status'] == 'uncertain' and len(calls) == 2\n    assert all(not item['safe_to_retry'] for item in result['items'])\n    again = authorized(case, resume=True)\n    assert again['status'] == 'uncertain' and len(calls) == 2\n\n\ndef test_success_requires_durable_intent_and_does_not_repeat(case, monkeypatch):\n    path = case['root']/'metrics/runs'/(case['run_id']+'.json')\n\n    def respond(payload, count):\n        stored = json.loads(path.read_text())\n        item = next(item for item in stored['items'] if item['idempotency_key'] == payload['idempotency_key'])\n        assert item['status'] == 'uncertain'\n        return ack(payload)\n\n    calls = live(case, monkeypatch, respond)\n    assert authorized(case)['status'] == 'complete' and len(calls) == 2\n    assert authorized(case, resume=True)['status'] == 'complete' and len(calls) == 2\n\n\ndef test_reconciliation_confirms_without_resend_or_audience_expansion(case, monkeypatch):\n    def respond(payload, count):\n        if count == 2:\n            raise TimeoutError('Synthetic ambiguous response')\n        return ack(payload)\n\n    calls = live(case, monkeypatch, respond)\n    assert authorized(case)['status'] == 'uncertain'\n    case['audiences']['segments']['sample'].append({'recipient': 'user3@example.com', 'recipient_country': 'US'})\n    (case['root']/'audiences.json').write_text(json.dumps(case['audiences']))\n    monkeypatch.setattr(dispatch, 'reconcile_action', lambda item, **kwargs: ack(item['payload']))\n    result = authorized(case, resume=True)\n    assert result['status'] == 'complete' and len(result['items']) == 2 and len(calls) == 2\n\n\ndef test_not_applied_reconciliation_retries_same_key(case, monkeypatch):\n    calls = live(case, monkeypatch, lambda payload, count: None if count == 1 else ack(payload))\n    assert authorized(case)['status'] == 'uncertain'\n    monkeypatch.setattr(dispatch, 'reconcile_action', lambda item, **kwargs: ack(item['payload'], 'not_applied'))\n    assert authorized(case, resume=True)['status'] == 'complete'\n    assert len(calls) == 3 and calls[0]['idempotency_key'] == calls[-1]['idempotency_key']\n\n\ndef test_scope_change_preserves_run_and_excludes_effects(case, monkeypatch):\n    calls = live(case, monkeypatch)\n    authorized(case)\n    path = case['root']/'metrics/runs'/(case['run_id']+'.json')\n    before = path.read_bytes()\n    arms = case['arms']\n    arms[0]['body'] += ' Synthetic changed proposal.'\n    (case['root']/'copy'/(case['campaign']+'.json')).write_text(json.dumps(arms))\n    assert authorized(case, resume=True)['status'] == 'failed'\n    assert len(calls) == 2 and path.read_bytes() == before\n\n\ndef test_resume_rechecks_suppression_before_known_failed_retry(case, monkeypatch):\n    calls = live(case, monkeypatch, lambda payload, count: ack(payload, 'not_applied'))\n    assert authorized(case)['status'] == 'failed'\n    (case['root']/'metrics/suppression.csv').write_text('USER1+alias@example.com\\n')\n    result = authorized(case, resume=True)\n    assert result['counts']['blocked'] == 1 and len(calls) == 3\n\n\ndef test_persistence_failure_prevents_provider_effect(case, monkeypatch):\n    from scripts import runs\n    calls = live(case, monkeypatch)\n    monkeypatch.setattr(runs, 'save', lambda *a: (_ for _ in ()).throw(OSError('Synthetic persistence failure')))\n    assert authorized(case)['status'] in {'failed', 'uncertain'}\n    assert calls == []\n\n\ndef test_owned_broadcast_needs_no_segment_or_country(case):\n    registration = case['cfg'].registry['channels'][0]\n    registration.update(platform='discord', transport='post', **case['broadcast'])\n    (case['root']/'audiences.json').unlink()\n    result = execute(case)\n    assert result['status'] == 'simulated' and len(result['items']) == 1\n    assert result['items'][0]['payload']['destination'] == case['broadcast']['destination']\n\n\ndef test_missing_broadcast_destination_blocks(case):\n    case['cfg'].registry['channels'][0].update(platform='discord', transport='post', audience_mode='owned_broadcast')\n    assert execute(case)['status'] == 'blocked'\n\n\ndef test_conflicting_duplicate_metadata_blocks_instead_of_choosing(case):\n    case['audiences']['segments']['sample'].append({'recipient': 'USER1+tag@example.com', 'recipient_country': 'DE'})\n    (case['root']/'audiences.json').write_text(json.dumps(case['audiences']))\n    result = execute(case)\n    assert result['counts']['blocked'] == 1 and result['duplicate_count'] == 1\n\n\ndef test_channel_capabilities_and_doctor_are_not_live_proof(case, monkeypatch, capsys):\n    from scripts import cli\n    resource = case['root']/'synthetic-mail.ps1'\n    resource.write_text('# Synthetic resource')\n    monkeypatch.setenv('PROMO_SEND_GMAIL', str(resource))\n    assert cli.main(['--config', str(case['root']), 'channels', 'list', '--json']) == 0\n    rows = json.loads(capsys.readouterr().out)['channels']\n    assert rows[0]['implemented'] and rows[0]['configured'] and rows[0]['live_proven'] == 'not_run'\n    assert cli.main(['--config', str(case['root']), 'doctor', '--json']) == 0\n    assert json.loads(capsys.readouterr().out)['status'] == 'ready'\n\n\ndef test_unavailable_selected_resource_is_not_ready(case, monkeypatch, capsys):\n    from scripts import cli\n    monkeypatch.setenv('PROMO_SEND_GMAIL', str(case['root']/'missing-helper'))\n    assert cli.main(['--config', str(case['root']), 'doctor', '--json']) != 0\n    assert json.loads(capsys.readouterr().out)['status'] == 'not_ready'\n\n\n@pytest.mark.parametrize('platform', ['discord', 'mastodon', 'bluesky'])\n@pytest.mark.parametrize('response', SAMPLE['adapter_responses'])\ndef test_actual_network_adapters_require_remote_proof(monkeypatch, platform, response):\n    import urllib.request\n    for name, value in SAMPLE['credentials'].items():\n        monkeypatch.setenv(name, value)\n    payload = {**SAMPLE['adapter_payload'], 'platform': platform}\n    if platform in SAMPLE['owned_accounts']:\n        payload.update(SAMPLE['owned_accounts'][platform]['payload'])\n    requests = []\n\n    class Reply:\n        def __init__(self, value):\n            self.value = value\n\n        def __enter__(self):\n            return self\n\n        def __exit__(self, *args):\n            return False\n\n        def read(self):\n            return json.dumps(self.value).encode()\n\n    def respond(request, **kwargs):\n        if request.full_url.endswith('verify_credentials'):\n            return Reply(SAMPLE['owned_accounts']['mastodon']['authenticated'])\n        requests.append(request)\n        return Reply(SAMPLE['session'] if request.full_url.endswith('createSession') else response['remote'])\n\n    monkeypatch.setattr(urllib.request, 'urlopen', respond)\n    result = providers.get(platform).publish(payload, live=True)\n    assert (result['status'] == 'sent') is response['confirmed']\n    assert len(requests) == (2 if platform == 'bluesky' else 1)\n    if response['confirmed']:\n        assert dispatch.matching_receipt(result, payload)\n    if platform == 'mastodon':\n        import hashlib\n        headers = {key.lower(): value for key, value in requests[0].header_items()}\n        assert headers['idempotency-key'] == hashlib.sha256(payload['idempotency_key'].encode()).hexdigest()\n\n\n@pytest.mark.parametrize('response', SAMPLE['adapter_responses'])\ndef test_actual_email_requires_structured_message_id(case, monkeypatch, response):\n    resource = case['root']/'synthetic-mail.ps1'\n    resource.write_text('# Synthetic process seam')\n    monkeypatch.setattr(providers, 'SEND_GMAIL_PS1', resource)\n    payload = copy.deepcopy(SAMPLE['email_payload'])\n    reply = {**email_contract.request(payload), **SAMPLE['receipt'], 'message_id': response['remote'].get('id')}\n    calls = []\n\n    def process(argv, **kwargs):\n        calls.append(argv)\n        return subprocess.CompletedProcess(argv, 0, json.dumps(reply), '')\n\n    monkeypatch.setattr(subprocess, 'run', process)\n    result = providers.EmailProvider().publish(payload, live=True)\n    assert (result['status'] == 'sent') is response['confirmed'] and len(calls) == 1\n    if response['confirmed']:\n        assert dispatch.matching_receipt(result, payload)\n\n\n@pytest.mark.parametrize('reply', SAMPLE['schedule_responses'])\ndef test_schedule_receipt_and_cli_exit_agree(case, monkeypatch, capsys, reply):\n    from scripts import cli\n    helper = case['root']/'synthetic-reminder.py'\n    helper.write_text('# Synthetic process seam')\n    monkeypatch.setattr(schedule_bridge, 'REMINDER', helper)\n    calls = []\n\n    def process(argv, **kwargs):\n        calls.append(argv)\n        return subprocess.CompletedProcess(argv, reply['rc'], reply['stdout'], '')\n\n    monkeypatch.setattr(subprocess, 'run', process)\n    rc = cli.main(['--config', str(case['root']), 'plan', '--campaign', case['campaign']])\n    result = json.loads(capsys.readouterr().out)\n    assert (rc == 0) is reply['ok'] and (result['status'] == 'complete') is reply['ok']\n    assert result['scheduled'] == int(reply['ok']) and len(calls) == 1\n\n\ndef test_interruption_keeps_uncertainty_and_does_not_resend(case, monkeypatch):\n    def interrupted(payload, count):\n        raise KeyboardInterrupt\n\n    calls = live(case, monkeypatch, interrupted)\n    with pytest.raises(KeyboardInterrupt):\n        authorized(case)\n    stored = json.loads((case['root']/'metrics/runs'/(case['run_id']+'.json')).read_text())\n    assert stored['items'][0]['status'] == 'uncertain'\n    live(case, monkeypatch)\n    result = authorized(case, resume=True)\n    assert result['status'] == 'uncertain' and len(calls) == 1\n\n\n@pytest.mark.parametrize('malformed', [None, {}, [], {'schema_version': 0}])\ndef test_malformed_saved_run_is_preserved(case, malformed):\n    directory = case['root']/'metrics/runs'\n    directory.mkdir()\n    path = directory/(case['run_id']+'.json')\n    path.write_text(json.dumps(malformed))\n    before = path.read_bytes()\n    assert execute(case, run_id=case['run_id'], resume=True)['status'] == 'failed'\n    assert path.read_bytes() == before\n\n\ndef test_cli_run_dry_and_blocked_exit_contract(case, capsys):\n    from scripts import cli\n    args = ['--config', str(case['root']), 'run', '--once', '--campaign', case['campaign'], '--run-id', case['run_id']]\n    assert cli.main(args) == 0\n    result = json.loads(capsys.readouterr().out)\n    assert result['status'] == 'simulated' and sum(result['counts'].values()) == len(result['items'])\n    assert cli.main(args) != 0\n    assert json.loads(capsys.readouterr().out)['status'] == 'failed'\n    assert cli.main(args + ['--resume']) == 0\n    capsys.readouterr()\n    assert cli.main(['--config', str(case['root']), 'run', '--campaign', case['campaign'], '--channel', 'absent']) != 0\n    assert json.loads(capsys.readouterr().out)['status'] == 'blocked'\n\n\n@pytest.mark.parametrize('linked', [False, True])\n@pytest.mark.parametrize('visibility', SAMPLE['visibility_responses'])\ndef test_actual_private_boundary_normal_and_linked(tmp_path, monkeypatch, synthetic_private_metadata, linked, visibility):\n    from scripts import private_storage\n    monkeypatch.setattr(private_storage, 'repository', synthetic_private_metadata)\n    root = tmp_path/'synthetic-companion'\n    root.mkdir()\n    if linked:\n        (root/'.git').write_text('gitdir: ../synthetic-control/worktrees/example\\n')\n    else:\n        (root/'.git').mkdir()\n    (root/'product.json').write_text(json.dumps(SAMPLE['product']))\n    (root/'registry.json').write_text(json.dumps(SAMPLE['registry']))\n    calls = []\n\n    def metadata(argv):\n        calls.append(argv)\n        if argv[0] == 'gh':\n            return visibility\n        if '--show-toplevel' in argv:\n            return str(root)\n        if argv[-1:] == ['remote']:\n            return 'origin'\n        if argv[-3:] == ['rev-parse', '--verify', 'HEAD']:\n            return '1'*40\n        if 'get-url' in argv and '--all' in argv and argv[-1] == 'origin':\n            return SAMPLE['origin']\n        raise AssertionError('unexpected Git metadata query')\n\n    monkeypatch.setattr(private_storage, '_run', metadata)\n    if visibility == SAMPLE['visibility_responses'][0]:\n        assert config.Config(root).metrics_dir() == root/'metrics'\n    else:\n        with pytest.raises(config.ConfigError):\n            config.Config(root)\n        assert not (root/'metrics').exists()\n    assert any('--show-toplevel' in argv for argv in calls)\n\n\ndef test_unversioned_and_source_storage_fail_before_metadata(tmp_path, monkeypatch, synthetic_private_metadata):\n    from scripts import private_storage\n    monkeypatch.setattr(private_storage, 'repository', synthetic_private_metadata)\n    monkeypatch.setattr(private_storage, '_run', lambda argv: pytest.fail('unversioned/source roots need no metadata lookup'))\n    for root in (tmp_path, private_storage.ROOT):\n        with pytest.raises(config.ConfigError):\n            config.Config(root)\n\n\n@pytest.mark.parametrize('relative', ['metrics', 'metrics/runs', 'metrics/events.jsonl',\n                                      'compliance/consent-ledger.jsonl', 'audiences.json',\n                                      'copy/'+SAMPLE['campaign']+'.json'])\ndef test_escaping_data_links_are_rejected(case, tmp_path, monkeypatch, relative):\n    path = case['root']/relative\n    outside = tmp_path/'synthetic-outside'\n    outside.mkdir()\n    directory = relative in {'metrics', 'metrics/runs'}\n    if path.exists():\n        if path.is_dir():\n            path.rmdir()  # The generated metrics directory is empty in a fresh case.\n        else:\n            path.unlink()\n    path.parent.mkdir(parents=True, exist_ok=True)\n    target = outside if directory else outside/'synthetic-data.json'\n    if not directory:\n        target.write_text(json.dumps(SAMPLE['arms'] if relative.startswith('copy/') else SAMPLE['audiences']))\n    if directory:\n        import os\n        if os.name == 'nt':\n            import _winapi\n            _winapi.CreateJunction(str(target), str(path))\n        else:\n            path.symlink_to(target, target_is_directory=True)\n    else:\n        # Windows file symlinks need unavailable privileges. Control only canonicalization;\n        # actual directory junctions above exercise the filesystem boundary too.\n        original_resolve = Path.resolve\n\n        def resolved(value, *args, **kwargs):\n            return target if value == path else original_resolve(value, *args, **kwargs)\n\n        monkeypatch.setattr(Path, 'resolve', resolved)\n    result = execute(case)\n    assert result['status'] in {'failed', 'blocked'}\n    assert not (outside/'events.jsonl').exists()\n\n\ndef test_highest_environment_selection_does_not_fall_through(case, monkeypatch):\n    monkeypatch.setenv('PROMO_CONFIG_DIR', str(case['root']/'missing'))\n    monkeypatch.setenv('PROMOTION_ASSISTANT_CONFIG', str(case['root']))\n    with pytest.raises(config.ConfigError):\n        config.load()\n\n\n@pytest.mark.parametrize('platform', ['email', 'discord', 'mastodon', 'bluesky'])\ndef test_existing_provider_dry_gate_control(platform):\n    # Positive controls also pass in the immutable initial source; unmocked effects fail globally.\n    result = providers.get(platform).publish(SAMPLE['adapter_payload'], live=False)\n    assert result['status'] != 'sent'\n\n\ndef test_existing_suppression_gate_control():\n    from scripts import compliance\n    payload = {**SAMPLE['adapter_payload'], 'platform': 'email', 'transport': 'smtp',\n               'recipient_country': SAMPLE['audiences']['segments']['sample'][0]['recipient_country'],\n               'from_addr': SAMPLE['product']['from_addr'],\n               'physical_address': SAMPLE['product']['compliance']['physical_address'],\n               'unsubscribe': SAMPLE['product']['compliance']['unsubscribe_url']}\n    assert compliance.check(payload, policy={}, suppression=set(), consent={})[0]\n    assert not compliance.check(payload, policy={}, suppression={payload['recipient']}, consent={})[0]\n\n\n@pytest.mark.parametrize('recipient', SAMPLE['invalid_recipients'])\ndef test_malformed_email_never_becomes_guessed_destination(case, recipient):\n    case['audiences']['segments']['sample'][0]['recipient'] = recipient\n    (case['root']/'audiences.json').write_text(json.dumps(case['audiences']))\n    result = execute(case)\n    assert result['counts']['blocked'] == 1 and result['items'][0]['status'] == 'blocked'\n\n\n@pytest.mark.parametrize('country', SAMPLE['invalid_countries'])\ndef test_invalid_recipient_country_blocks(case, country):\n    case['audiences']['segments']['sample'][0]['recipient_country'] = country\n    (case['root']/'audiences.json').write_text(json.dumps(case['audiences']))\n    assert execute(case)['counts']['blocked'] == 1\n\n\ndef test_review_checks_the_end_of_full_body(case):\n    case['arms'][0]['body'] = SAMPLE['late_banned_claim']\n    (case['root']/'copy'/(case['campaign']+'.json')).write_text(json.dumps(case['arms']))\n    result = execute(case)\n    assert result['status'] == 'blocked' and result['counts']['blocked'] == 2\n    assert all(item['payload']['body'] == SAMPLE['late_banned_claim'] for item in result['items'])\n\n\n@pytest.mark.parametrize('platform', ['discord', 'mastodon', 'bluesky'])\ndef test_oversized_reviewed_payload_is_not_silently_truncated(monkeypatch, platform):\n    for name, value in SAMPLE['credentials'].items():\n        monkeypatch.setenv(name, value)\n    payload = {**SAMPLE['adapter_payload'], 'body': SAMPLE['oversized_body'], 'platform': platform}\n    result = providers.get(platform).publish(payload, live=True)\n    assert dispatch.matching_receipt(result, payload, 'not_applied')\n",
    "tests/test_audit_fixes.py": "\"\"\"Round-2 audit-fix regression guards (each fails on the PRE-fix code, passes after).\n\nCovers the three round-2 audit findings:\n  F1 (low) dispatch doc/impl drift  -> second factor can now ENFORCE a configured expected token\n            (constant-time equality) instead of accepting any non-empty value; existence-only\n            stays the documented default when no expected token is configured.\n  F2 (low) live email subprocess arg-binding -> recipient is validated as a single email and any\n            recipient/subject/body that starts with '-' is refused BEFORE spawning powershell.\n  F3 (info) over-broad `*.jsonl` ignore -> narrowed so committed test fixtures / reference shards\n            are no longer silently swallowed, while stray runtime jsonl stays ignored.\n\nThese are deterministic, hermetic, and never perform real egress (the email subprocess is spied).\n\"\"\"\nimport json\nimport subprocess as _sp\nimport tempfile\nfrom pathlib import Path\n\nimport pytest\n\nfrom scripts import config as CFG\nfrom scripts import dispatch as D\nfrom scripts import providers as P\nfrom scripts import email_contract as EMAIL\n\n_ROOT = Path(__file__).resolve().parents[1]\n\n\n# ----------------------------------------------------------------------------- F1\ndef _mk_cfg(tmp, *, channel_extra=None):\n    root = Path(tmp)\n    (root / \"product.json\").write_text(json.dumps({\n        \"name\": \"T\", \"send_mode\": \"live\", \"banned_claims\": [],\n    }), encoding=\"utf-8\")\n    ch = {\"slug\": \"email-pool\", \"platform\": \"email\", \"warmup_state\": \"normal\"}\n    if channel_extra:\n        ch.update(channel_extra)\n    (root / \"registry.json\").write_text(json.dumps({\"channels\": [ch]}), encoding=\"utf-8\")\n    return CFG.Config(root)\n\n\ndef test_f1_authorized_enforces_configured_expected_token():\n    env_good = {\"PROMO_LIVE_AUTHORIZED_EMAIL\": \"s3cret\"}\n    env_wrong = {\"PROMO_LIVE_AUTHORIZED_EMAIL\": \"WRONG-but-nonempty\"}\n    # match required when an expected secret is configured\n    assert D._authorized(\"email\", \"live\", env=env_good, expected=\"s3cret\")[0] is True\n    # the core fix: a NON-EMPTY but mismatching token must NOT authorize (pre-fix it did)\n    assert D._authorized(\"email\", \"live\", env=env_wrong, expected=\"s3cret\")[0] is False\n    # existence-only fallback preserved when no expected secret is configured\n    assert D._authorized(\"email\", \"live\", env=env_wrong, expected=None)[0] is True\n    # factor-1 + presence still fail-closed\n    assert D._authorized(\"email\", \"dry_run\", env=env_good, expected=None)[0] is False\n    assert D._authorized(\"email\", \"live\", env={}, expected=None)[0] is False\n\n\ndef test_f1_config_exposes_per_channel_expected_token():\n    with tempfile.TemporaryDirectory() as t:\n        cfg = _mk_cfg(t, channel_extra={\"live_authorize_token\": \"abc123\"})\n        assert cfg.live_authorize_token(\"email-pool\") == \"abc123\"\n    with tempfile.TemporaryDirectory() as t:\n        cfg = _mk_cfg(t)  # unset -> existence-only default\n        assert cfg.live_authorize_token(\"email-pool\") is None\n        assert cfg.live_authorize_token(\"missing-channel\") is None\n\n\n# ----------------------------------------------------------------------------- F2\nclass _Spy:\n    def __init__(self):\n        self.calls = []\n\n    def __call__(self, cmd, *a, **kw):\n        self.calls.append(cmd)\n\n        class _R:\n            returncode = 0\n            stdout = json.dumps({**json.loads(cmd[cmd.index(\"-RequestJson\")+1]),\n                                 **json.loads((_ROOT/'tests/fixtures/promotion.json').read_text())['receipt']})\n            stderr = \"\"\n        return _R()\n\n\ndef _wire_email(monkeypatch, tmpdir):\n    ps1 = Path(tmpdir) / \"send-gmail.ps1\"\n    ps1.write_text(\"# stub\", encoding=\"utf-8\")\n    monkeypatch.setattr(P, \"SEND_GMAIL_PS1\", ps1)\n    spy = _Spy()\n    monkeypatch.setattr(P.subprocess, \"run\", spy)\n    return spy\n\n\ndef _email_payload(**overrides):\n    payload = json.loads((_ROOT/'tests/fixtures/promotion.json').read_text())['email_payload']\n    return {**payload, **overrides}\n\n\ndef test_f2_dash_leading_recipient_refused_without_spawning(monkeypatch):\n    with tempfile.TemporaryDirectory() as t:\n        spy = _wire_email(monkeypatch, t)\n        prov = P.EmailProvider()\n        r = prov.publish(_email_payload(recipient=\"--Command\"), live=True)\n        assert r[\"status\"] == \"not_applied\"\n        assert spy.calls == [], \"must refuse BEFORE spawning powershell\"\n\n\ndef test_f2_non_email_recipient_refused(monkeypatch):\n    with tempfile.TemporaryDirectory() as t:\n        spy = _wire_email(monkeypatch, t)\n        prov = P.EmailProvider()\n        r = prov.publish(_email_payload(recipient=\"not-an-email\"), live=True)\n        assert r[\"status\"] == \"not_applied\"\n        assert spy.calls == []\n\n\ndef test_f2_dash_leading_subject_or_body_refused(monkeypatch):\n    with tempfile.TemporaryDirectory() as t:\n        spy = _wire_email(monkeypatch, t)\n        prov = P.EmailProvider()\n        assert prov.publish(_email_payload(subject=\"-Foo\"),\n                            live=True)[\"status\"] == \"not_applied\"\n        assert prov.publish(_email_payload(body=\"-rm\"),\n                            live=True)[\"status\"] == \"not_applied\"\n        assert spy.calls == []\n\n\ndef test_f2_valid_email_still_reaches_live_transport(monkeypatch):\n    with tempfile.TemporaryDirectory() as t:\n        spy = _wire_email(monkeypatch, t)\n        prov = P.EmailProvider()\n        payload = json.loads((_ROOT/'tests/fixtures/promotion.json').read_text())['email_payload']\n        r = prov.publish(payload, live=True)\n        assert r[\"status\"] == \"sent\"\n        assert len(spy.calls) == 1, \"valid recipient must still invoke the live path\"\n        cmd = spy.calls[0]\n        assert \"-RequestJson\" in cmd\n        transported = json.loads(cmd[cmd.index(\"-RequestJson\")+1])\n        assert transported == EMAIL.request(payload)\n        assert transported[\"body\"] == payload[\"rendered_body\"]\n\n\n# ----------------------------------------------------------------------------- F3\ndef _check_ignored(path: str):\n    \"\"\"Return True if `path` is git-ignored at the repo root, None if git is unavailable.\"\"\"\n    try:\n        r = _sp.run([\"git\", \"-C\", str(_ROOT), \"check-ignore\", \"-q\", path],\n                    capture_output=True, text=True)\n    except Exception:\n        return None\n    if r.returncode == 0:\n        return True\n    if r.returncode == 1:\n        return False\n    return None  # 128 = not a git work tree\n\n\ndef test_f3_legit_fixture_jsonl_not_ignored():\n    res = _check_ignored(\"tests/fixtures/sample_events.jsonl\")\n    if res is None:\n        pytest.skip(\"git unavailable / not a work tree\")\n    assert res is False, \"committed test-fixture .jsonl must NOT be ignored (over-broad ignore fix)\"\n\n\ndef test_f3_runtime_jsonl_still_ignored():\n    for stray in (\"metrics/events.jsonl\", \"stray_runtime.jsonl\", \"dry-run.jsonl\"):\n        res = _check_ignored(stray)\n        if res is None:\n            pytest.skip(\"git unavailable / not a work tree\")\n        assert res is True, \"runtime jsonl %r must stay ignored (defensive default preserved)\" % stray\n\n\ndef test_f3_fixture_file_exists_on_disk():\n    # the fixture is really committed (proves the ignore narrowing is load-bearing, not just text)\n    assert (_ROOT / \"tests\" / \"fixtures\" / \"sample_events.jsonl\").is_file()\n",
    "tests/test_discord_live.py": "\"\"\"E23 -- DiscordOwnServerProvider live publish (own-server announce via REST bot).\n\nLive network is never touched: urlopen is mocked. Verifies the two-switch contract still holds\n(live=False stays a deferred-gap), credentials are required, a real 200 maps to 'sent', a 429 maps\nto 'throttled' so the caller's AIMD can react, and other HTTP errors surface as 'error'.\n\"\"\"\nimport io\nimport json\nimport urllib.error\nfrom unittest import mock\n\nfrom scripts import providers as P\n\n\ndef _resp(obj):\n    m = mock.MagicMock()\n    m.read.return_value = json.dumps(obj).encode(\"utf-8\")\n    m.__enter__.return_value = m\n    m.__exit__.return_value = False\n    return m\n\n\ndef _http_error(code, body=\"{}\"):\n    return urllib.error.HTTPError(\"u\", code, \"err\", {}, io.BytesIO(body.encode(\"utf-8\")))\n\n\nPAYLOAD = {\"subject\": \"New free models live\", \"body\": \"changelog here\", \"cta\": \"https://x/register?aff=a\"}\n\n\ndef test_not_live_is_deferred_gap():\n    r = P.DiscordOwnServerProvider().publish(PAYLOAD, live=False)\n    assert r[\"status\"] == \"deferred-gap\"\n\n\ndef test_missing_credentials_errors(monkeypatch):\n    monkeypatch.delenv(\"PROMO_DISCORD_BOT_TOKEN\", raising=False)\n    monkeypatch.delenv(\"PROMO_DISCORD_ANNOUNCE_CHANNEL_ID\", raising=False)\n    r = P.DiscordOwnServerProvider().publish(PAYLOAD, live=True)\n    assert r[\"status\"] == \"not_applied\" and \"not in env\" in r[\"reason\"]\n\n\ndef test_non_numeric_channel_rejected(monkeypatch):\n    monkeypatch.setenv(\"PROMO_DISCORD_BOT_TOKEN\", \"tok\")\n    monkeypatch.setenv(\"PROMO_DISCORD_ANNOUNCE_CHANNEL_ID\", \"not-a-number\")\n    r = P.DiscordOwnServerProvider().publish(PAYLOAD, live=True)\n    assert r[\"status\"] == \"not_applied\" and \"numeric\" in r[\"reason\"]\n\n\ndef test_live_success_maps_to_sent(monkeypatch):\n    monkeypatch.setenv(\"PROMO_DISCORD_BOT_TOKEN\", \"tok\")\n    monkeypatch.setenv(\"PROMO_DISCORD_ANNOUNCE_CHANNEL_ID\", \"123456789\")\n    captured = {}\n\n    def fake_urlopen(req, timeout=None):\n        captured[\"url\"] = req.full_url\n        captured[\"auth\"] = req.headers.get(\"Authorization\")\n        captured[\"body\"] = json.loads(req.data.decode(\"utf-8\"))[\"content\"]\n        return _resp({\"id\": \"999\"})\n\n    with mock.patch.object(P.urllib.request, \"urlopen\", fake_urlopen):\n        r = P.DiscordOwnServerProvider().publish(PAYLOAD, live=True)\n    assert r[\"status\"] == \"sent\" and r[\"message_id\"] == \"999\" and r[\"channel_id\"] == \"123456789\"\n    assert captured[\"url\"].endswith(\"/channels/123456789/messages\")\n    assert captured[\"auth\"] == \"Bot tok\"\n    # message composes subject (bold) + body + cta, and carries the affiliate CTA\n    assert \"**New free models live**\" in captured[\"body\"] and \"aff=a\" in captured[\"body\"]\n\n\ndef test_empty_message_errors(monkeypatch):\n    monkeypatch.setenv(\"PROMO_DISCORD_BOT_TOKEN\", \"tok\")\n    monkeypatch.setenv(\"PROMO_DISCORD_ANNOUNCE_CHANNEL_ID\", \"123\")\n    r = P.DiscordOwnServerProvider().publish({\"subject\": \"\", \"body\": \"\", \"cta\": \"\"}, live=True)\n    assert r[\"status\"] == \"not_applied\" and \"empty\" in r[\"reason\"]\n\n\ndef test_429_maps_to_throttled(monkeypatch):\n    monkeypatch.setenv(\"PROMO_DISCORD_BOT_TOKEN\", \"tok\")\n    monkeypatch.setenv(\"PROMO_DISCORD_ANNOUNCE_CHANNEL_ID\", \"123\")\n    with mock.patch.object(P.urllib.request, \"urlopen\", side_effect=_http_error(429, '{\"retry_after\":2}')):\n        r = P.DiscordOwnServerProvider().publish(PAYLOAD, live=True)\n    assert r[\"status\"] == \"throttled\"\n\n\ndef test_403_maps_to_error(monkeypatch):\n    monkeypatch.setenv(\"PROMO_DISCORD_BOT_TOKEN\", \"tok\")\n    monkeypatch.setenv(\"PROMO_DISCORD_ANNOUNCE_CHANNEL_ID\", \"123\")\n    with mock.patch.object(P.urllib.request, \"urlopen\", side_effect=_http_error(403, '{\"message\":\"Missing Access\"}')):\n        r = P.DiscordOwnServerProvider().publish(PAYLOAD, live=True)\n    assert r[\"status\"] == \"error\" and r[\"code\"] == 403\n",
    "tests/test_expansion.py": "#!/usr/bin/env python3\n\"\"\"Regression guard for the 2026-07 expansion: over-claim floor, Mastodon/Bluesky providers,\nManualPrepProvider prep/record loop. Every provider is exercised in NON-live mode (no network);\nthe over-claim guard is pure text; the manual loop is checked structurally.\"\"\"\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nSCRIPTS = os.path.abspath(os.path.join(HERE, \"..\", \"skills\", \"promotion-assistant\", \"scripts\"))\nif SCRIPTS not in sys.path:\n    sys.path.insert(0, SCRIPTS)\n\nimport compliance  # noqa: E402\nimport providers   # noqa: E402\nimport content     # noqa: E402\n\n\nclass _FakeCfg:\n    \"\"\"Minimal cfg stand-in for the pure content generator (no config repo needed).\"\"\"\n    def __init__(self):\n        self.product = {\"product\": \"TestGW\", \"url\": \"https://tg.example\",\n                        \"value_props\": [\"cheaper and more stable\", \"generous free models\"]}\n    aff_base = \"https://tg.example/register?aff=\"\n    banned_claims = []\n\n\n# ---- over-claim floor (built-in, non-removable) --------------------------------------------------\ndef _check(body, banned=None):\n    return compliance.check({\"body\": body, \"transport\": \"post\"},\n                            policy={\"banned_claims\": banned or []}, suppression=set(), consent={})\n\n\ndef test_overclaim_floor_blocks_scam_superlatives():\n    for bad in (\"Get unlimited free tokens\", \"no limits, ever\", \"100% free forever\", \"never rate limited\"):\n        ok, reasons = _check(bad)\n        assert not ok, \"should block over-claim: %r\" % bad\n        assert any(\"banned claim\" in r for r in reasons)\n\n\ndef test_overclaim_floor_allows_honest_copy():\n    ok, _ = _check(\"Cheaper, more stable OpenAI-compatible gateway with generous free models\")\n    assert ok\n\n\ndef test_overclaim_floor_survives_zero_width_obfuscation():\n    ok, _ = _check(\"un\u200blimited free access\")  # zero-width space inside 'unlimited'\n    assert not ok  # normalized match still catches it\n\n\ndef test_overclaim_floor_is_not_removable_by_empty_banned_claims():\n    # a product with an explicitly empty banned_claims list still gets the floor\n    ok, _ = _check(\"unlimited free\", banned=[])\n    assert not ok\n\n\n# ---- Mastodon / Bluesky providers: non-live is a clean no-op, missing creds is a clean error -----\ndef test_mastodon_non_live_is_not_live():\n    r = providers.MastodonProvider().publish({\"body\": \"x\"}, live=False)\n    assert r[\"status\"] == \"deferred-gap\" and r[\"platform\"] == \"mastodon\"\n\n\ndef test_mastodon_live_without_creds_errors_cleanly(monkeypatch):\n    monkeypatch.delenv(\"PROMO_MASTODON_INSTANCE\", raising=False)\n    monkeypatch.delenv(\"PROMO_MASTODON_TOKEN\", raising=False)\n    r = providers.MastodonProvider().publish({\"body\": \"x\"}, live=True)\n    assert r[\"status\"] == \"not_applied\" and \"PROMO_MASTODON\" in r[\"reason\"]\n\n\ndef test_bluesky_non_live_is_not_live():\n    r = providers.BlueskyProvider().publish({\"body\": \"x\"}, live=False)\n    assert r[\"status\"] == \"deferred-gap\" and r[\"platform\"] == \"bluesky\"\n\n\ndef test_bluesky_live_without_creds_errors_cleanly(monkeypatch):\n    monkeypatch.delenv(\"PROMO_BLUESKY_HANDLE\", raising=False)\n    monkeypatch.delenv(\"PROMO_BLUESKY_APP_PASSWORD\", raising=False)\n    r = providers.BlueskyProvider().publish({\"body\": \"x\"}, live=True)\n    assert r[\"status\"] == \"not_applied\" and \"PROMO_BLUESKY\" in r[\"reason\"]\n\n\ndef test_mastodon_bluesky_are_live_transport_in_registry():\n    reg = providers.build_registry()\n    assert reg[\"mastodon\"].LIVE_TRANSPORT is True\n    assert reg[\"bluesky\"].LIVE_TRANSPORT is True\n    assert reg[\"x\"].LIVE_TRANSPORT is False  # X stays deferred\n\n\n# ---- ManualPrepProvider: never egresses, prep emits copy + checklist ------------------------------\ndef test_manual_prep_never_has_live_transport():\n    reg = providers.build_registry()\n    for slug in (\"reddit\", \"janitorai-card\", \"producthunt\", \"hackernews\"):\n        assert reg[slug].LIVE_TRANSPORT is False  # permanent -- a human is the actuator\n\n\ndef test_manual_prep_publish_never_sends():\n    # even asked to go live, a manual-prep provider must not egress\n    r = providers.build_registry()[\"reddit\"].publish({\"body\": \"x\"}, live=True)\n    assert r[\"status\"] == \"deferred-gap\"  # no network path exists\n\n\ndef test_manual_prep_emits_copy_and_checklist():\n    prov = providers.build_registry()[\"reddit\"]\n    out = prov.prep({\"subject\": \"hook\", \"body\": \"text\", \"cta\": \"https://x/register?aff=a\"})\n    assert out[\"status\"] == \"prepared\"\n    assert \"hook\" in out[\"copy\"] and \"register?aff=a\" in out[\"copy\"]\n    assert isinstance(out[\"checklist\"], list) and out[\"checklist\"]  # a real per-surface checklist\n    assert \"megathread\" in out[\"surface\"].lower()\n\n\n# ---- SEO content generator: honest guides, aff-stamped, over-claim-guarded ----------------------\ndef test_content_guide_renders_with_aff_link():\n    g = content.build_guide(_FakeCfg(), \"sillytavern\", aff_code=\"seo_st\")\n    assert g[\"status\"] == \"ok\"\n    assert \"SillyTavern\" in g[\"markdown\"] and \"register?aff=seo_st\" in g[\"markdown\"]\n    assert \"base-URL\" in g[\"markdown\"] or \"Base URL\" in g[\"markdown\"]\n\n\ndef test_content_all_frontends():\n    guides = content.build_all(_FakeCfg(), aff_code=\"x\")\n    fes = {g[\"frontend\"] for g in guides if g.get(\"status\") == \"ok\"}\n    assert {\"janitorai\", \"sillytavern\", \"risu\", \"agnai\"} <= fes\n\n\ndef test_content_unknown_frontend_errors():\n    g = content.build_guide(_FakeCfg(), \"nosuchfrontend\")\n    assert g[\"status\"] == \"error\"\n\n\ndef test_content_proxy_card_has_aff():\n    c = content.build_proxy_card(_FakeCfg(), aff_code=\"card_a\")\n    assert c[\"status\"] == \"ok\" and \"register?aff=card_a\" in c[\"blurb\"]\n\n\ndef test_content_over_claim_is_refused():\n    # a cfg whose value_props over-claim must be BLOCKED by the floor at render time\n    cfg = _FakeCfg()\n    cfg.product = {**cfg.product, \"value_props\": [\"unlimited free tokens forever\"]}\n    g = content.build_guide(cfg, \"janitorai\")\n    assert g[\"status\"] == \"blocked\"\n\n\n# ---- referral module: stable codes, aff-stamped invite, over-claim-guarded, attribution ----------\nimport referral  # noqa: E402\n\n\ndef test_referral_code_is_stable_and_urlsafe():\n    c1 = referral.advocate_code(\"CoolUser\")\n    c2 = referral.advocate_code(\"cooluser\")  # case-insensitive -> same code (idempotent)\n    assert c1 == c2 and c1.startswith(\"r_\")\n    assert all(ch.isalnum() or ch == \"_\" for ch in c1)\n\n\ndef test_referral_invite_carries_advocate_code():\n    r = referral.invite_copy(_FakeCfg(), \"alice\")\n    assert r[\"status\"] == \"ok\"\n    assert r[\"code\"] in r[\"aff_url\"] and r[\"code\"] in r[\"copy\"]\n\n\ndef test_referral_invite_over_claim_refused():\n    cfg = _FakeCfg()\n    r = referral.invite_copy(cfg, \"bob\", reward_hint=\"unlimited free forever\")\n    assert r[\"status\"] == \"blocked\"\n\n\ndef test_referral_attribution():\n    code = referral.advocate_code(\"carol\")\n    evs = [{\"event_type\": \"click\", \"utm\": {\"content\": code}},\n           {\"event_type\": \"conversion\", \"utm\": {\"content\": code}},\n           {\"event_type\": \"conversion\", \"utm\": {\"content\": \"other\"}}]\n    a = referral.attribute(evs, code)\n    assert a[\"touches\"] == 2 and a[\"conversions\"] == 1 and a[\"converted\"] is True\n\n\n# ---- growth module: listing assets + keybot spec, guard-safe ------------------------------------\nimport growth  # noqa: E402\n\n\ndef test_growth_listing_has_tags_and_directories():\n    L = growth.listing(_FakeCfg())\n    assert \"openai\" in L[\"tags\"] and L[\"directories\"]\n    assert \"bump\" in L[\"bump_note\"].lower() and \"ring\" in L[\"bump_note\"].lower()  # anti-ring guard present\n\n\ndef test_growth_keybot_spec_is_compliant_text():\n    s = growth.keybot_spec(_FakeCfg())\n    assert \"/key\" in s and \"OWN server\" in s and \"register?aff=discord\" in s\n    assert \"Never DM users of OTHER servers\" in s\n",
    "tests/test_roadmap_deeper.py": "\"\"\"Deeper roadmap-capability assertions (batch-1 headroom).\n\nThese pin behaviors the existing E1-E12 gate does NOT cover: bandit *sub-linear regret* (not just\nfinal best-share), attribution *boundaries* (multi-touch last-non-direct ordering + direct-only\nfallback), throttle *stricter discipline* (warmup no-skip exactness, AIMD ramp ceiling, min-gap\npacing), delayed-conversion *window edge*, and reward *strong-negative ordering*. They assert\nproperties of the CURRENT implementation (all green), expanding the verifiable contract under the\nmutation-killable A-tier gate without breaking any existing contract.\n\"\"\"\nimport random\n\nfrom scripts import bandit as B\nfrom scripts import events as EV\nfrom scripts import metrics as M\nfrom scripts import throttle as TH\n\n\n# ---- D1 bandit sub-linear regret (deeper than E2's final best-share) ----\ndef test_bandit_sublinear_regret():\n    rng = random.Random(7)\n    sim = random.Random(11)\n    probs = {\"a0\": 0.3, \"a1\": 0.3, \"a2\": 0.7, \"a3\": 0.3}\n    best = 0.7\n    b = B.Bandit(None, gamma=1.0, rng=rng)\n    n = 400\n    half = n // 2\n    regret_first = regret_last = 0.0\n    for t in range(n):\n        d = b.select(list(probs), samples_for_propensity=20)\n        arm = d[\"arm_id\"]\n        r = 1.0 if sim.random() < probs[arm] else 0.0\n        b.update(arm, r)\n        inst = best - probs[arm]\n        if t < half:\n            regret_first += inst\n        else:\n            regret_last += inst\n    # Learning => per-round regret in the back half is far below the front half (sub-linear growth),\n    # and the converged regret rate is small relative to the all-suboptimal rate (0.4).\n    assert regret_last < regret_first * 0.5, (regret_first, regret_last)\n    assert regret_last / half < 0.1, regret_last / half\n\n\n# ---- D2 attribution: direct-only conversion falls back to the conversion event ----\ndef test_attribution_direct_only_fallback():\n    evs = [EV.make_event(\"email\", \"conversion\", subject_key=\"u2\", ts=5.0)]\n    a = M.attribute(evs)\n    assert len(a) == 1\n    assert a[0][\"attributed_channel\"] == \"email\"\n    assert a[0][\"attributed_arm\"] is None\n\n\n# ---- D3 attribution: last NON-direct touch wins across multiple touches (E6 has only one) ----\ndef test_attribution_last_non_direct_ordering():\n    evs = [\n        EV.make_event(\"reddit\", \"sent\", arm_id=\"X\", subject_key=\"u\", ts=1.0,\n                      propensity_p=0.5, policy_version=\"v\", utm={\"content\": \"X\"}),\n        EV.make_event(\"mastodon\", \"click\", arm_id=\"Y\", subject_key=\"u\", ts=2.0,\n                      utm={\"content\": \"Y\"}),\n        EV.make_event(\"reddit\", \"conversion\", subject_key=\"u\", ts=3.0),\n    ]\n    a = M.attribute(evs)\n    assert len(a) == 1\n    assert a[0][\"attributed_arm\"] == \"Y\"\n    assert a[0][\"attributed_channel\"] == \"mastodon\"\n\n\n# ---- D4 warmup state machine: no level-skipping, exact action gating ----\ndef test_warmup_no_skip_exact(tmp_path):\n    thr = TH.Throttle(tmp_path / \"s.json\", rng=random.Random(1))\n    pol = {\"day_cap\": 5, \"min_gap_sec\": 0}\n    assert thr.allow(\"a\", \"reddit\", \"post\", pol, account_stage=\"like\")[0] is False\n    assert thr.allow(\"a\", \"reddit\", \"comment\", pol, account_stage=\"follow_comment\")[0] is True\n    assert thr.allow(\"a\", \"reddit\", \"post\", pol, account_stage=\"follow_comment\")[0] is False\n    assert thr.allow(\"a\", \"reddit\", \"post\", pol, account_stage=\"normal\")[0] is True\n    # unknown/garbage stage must degrade to the most restrictive (browse: no actions)\n    assert thr.allow(\"a\", \"reddit\", \"like\", pol, account_stage=\"???\")[0] is False\n\n\n# ---- D5 AIMD additive ramp-up is capped at base_cap * max_growth_mult ----\ndef test_throttle_rampup_ceiling(tmp_path):\n    clock = [1000.0]\n    thr = TH.Throttle(tmp_path / \"s.json\", clock=lambda: clock[0], rng=random.Random(1))\n    pol = {\"day_cap\": 10, \"rampup\": {\"stable_days\": 1, \"factor\": 2.0}, \"max_growth_mult\": 3.0}\n    thr._bucket(\"a\", \"reddit\", \"post\", pol)  # initialize base_cap=10\n    for _ in range(20):\n        clock[0] += 2 * 86400.0  # advance two stable days each iteration\n        thr.on_stable_period(\"a\", \"reddit\", \"post\", pol)\n    cap = thr.state[thr._key(\"a\", \"reddit\", \"post\")][\"cap\"]\n    assert cap <= 10 * 3.0 + 1e-9, cap     # never exceeds the ceiling\n    assert cap > 10.0, cap                  # but it did grow\n\n\n# ---- D6 min-gap pacing blocks a too-soon second action ----\ndef test_throttle_min_gap_pacing(tmp_path):\n    clock = [1000.0]\n    thr = TH.Throttle(tmp_path / \"s.json\", clock=lambda: clock[0], rng=random.Random(1))\n    pol = {\"day_cap\": 50, \"min_gap_sec\": 600}\n    ok1 = thr.allow(\"a\", \"reddit\", \"post\", pol)\n    assert ok1[0] is True\n    clock[0] += 1.0  # only one second later\n    ok2 = thr.allow(\"a\", \"reddit\", \"post\", pol)\n    assert ok2[0] is False\n    assert \"min-gap\" in ok2[1]\n\n\n# ---- D7 delayed-conversion window edge (boundary E11 does not pin) ----\ndef test_delayed_conversion_window_edge():\n    now = 100000.0\n    # Exactly at the window edge: (now - last_send) == window -> NOT censored (strict <).\n    edge = [EV.make_event(\"c\", \"sent\", arm_id=\"z\", ts=now - 1000.0,\n                          propensity_p=0.5, policy_version=\"v\")]\n    r, s = M.reward_for_arm(edge, \"z\", conversion_window_s=1000, now=now)\n    assert s == \"ok\" and r is not None, (s, r)\n    # Just inside the window -> censored (not a negative).\n    inside = [EV.make_event(\"c\", \"sent\", arm_id=\"z\", ts=now - 999.0,\n                            propensity_p=0.5, policy_version=\"v\")]\n    r2, s2 = M.reward_for_arm(inside, \"z\", conversion_window_s=1000, now=now)\n    assert s2 == \"censored\" and r2 is None, (s2, r2)\n\n\n# ---- D8 reward strong-negative ordering (ban/complaint must rank below engagement) ----\ndef test_reward_strong_negative_ordering():\n    pos = [EV.make_event(\"c\", \"sent\", arm_id=\"p\", propensity_p=0.5, policy_version=\"v\"),\n           EV.make_event(\"c\", \"click\", arm_id=\"p\"),\n           EV.make_event(\"c\", \"conversion\", arm_id=\"p\")]\n    neg = [EV.make_event(\"c\", \"sent\", arm_id=\"n\", propensity_p=0.5, policy_version=\"v\"),\n           EV.make_event(\"c\", \"complaint\", arm_id=\"n\"),\n           EV.make_event(\"c\", \"blocked\", arm_id=\"n\")]\n    rp, _ = M.reward_for_arm(pos, \"p\")\n    rn, _ = M.reward_for_arm(neg, \"n\")\n    assert rp > rn, (rp, rn)\n    assert rn < 0.5, rn   # a net-negative arm squashes below the neutral midpoint\n",
    "skills/promotion-assistant/scripts/selftest.py": "#!/usr/bin/env python3\n\"\"\"Programmatic acceptance gate E1-E12 (self-evolve regression signals, all machine-judged).\n\nRun:  python skills/promotion-assistant/scripts/selftest.py\nExit 0 iff every core signal passes. Each check is deterministic (seeded). Tests that need the\nschedule-reminder base degrade to an EXPLICIT gap (never a silent skip) if the base is absent.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport os\nimport random\nimport sys\nimport tempfile\nfrom contextlib import contextmanager\nfrom pathlib import Path\nfrom unittest.mock import patch\n\n_HERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(_HERE.parent))\n\nfrom scripts import bandit as B          # noqa: E402\nfrom scripts import compliance as C      # noqa: E402\nfrom scripts import config as CFG        # noqa: E402\nfrom scripts import dispatch as D        # noqa: E402\nfrom scripts import events as EV         # noqa: E402\nfrom scripts import fingerprint as FP    # noqa: E402\nfrom scripts import metrics as M         # noqa: E402\nfrom scripts import orchestrate as ORCH  # noqa: E402\nfrom scripts import throttle as TH       # noqa: E402\nfrom scripts.schedule_bridge import ScheduleBridge  # noqa: E402\n\nR = []  # (id, name, ok, detail)\n\n\ndef rec(i, name, ok, detail=\"\"):\n    # Preserve the None GAP-sentinel: both main() and the pytest _assert branch on `ok is None`\n    # to degrade an absent optional base to a skip, not a hard fail. Coercing it to bool would\n    # defeat that contract and turn every environment-dependent gap into a spurious failure.\n    R.append((i, name, ok if ok is None else bool(ok), detail))\n\n\ndef _mk_config(tmp, send_mode=\"dry_run\"):\n    fixture = json.loads((_HERE.parent/'fixtures/promotion.json').read_text())\n    root = Path(tmp)\n    (root / \"channels\" / \"reddit-rp\").mkdir(parents=True, exist_ok=True)\n    (root / \"copy\").mkdir(parents=True, exist_ok=True)\n    (root / \"product.json\").write_text(json.dumps({\n        \"name\": \"TestProd\", \"send_mode\": send_mode,\n        \"aff_base\": \"https://x.test/register?aff=\",\n        \"banned_claims\": [\"100% uncensored\"],\n        \"compliance\": {\"physical_address\": \"1 Test St\", \"unsubscribe_url\": \"https://x.test/u\"},\n        \"from_addr\": \"promo@x.test\",\n    }, ensure_ascii=False), encoding=\"utf-8\")\n    (root / \"registry.json\").write_text(json.dumps({\"channels\": [\n        {\"slug\": \"reddit-rp\", \"platform\": \"reddit\", \"transport\": \"post\",\n         \"account_handle\": \"acct1\", \"warmup_state\": \"normal\", **fixture['broadcast']}\n    ]}, ensure_ascii=False), encoding=\"utf-8\")\n    (root / \"channels\" / \"reddit-rp\" / \"policy.json\").write_text(json.dumps({\n        \"day_cap\": 50, \"min_gap_sec\": 0\n    }), encoding=\"utf-8\")\n    (root / \"copy\" / \"camp.json\").write_text(json.dumps([\n        {\"id\": \"armA\", \"channel\": \"reddit-rp\", \"segment\": \"rp\", \"hook\": \"free proxy that stays up\",\n         \"body\": \"tried it for two months\", \"utm\": {\"source\": \"reddit\", \"content\": \"armA\"}},\n        {\"id\": \"armB\", \"channel\": \"reddit-rp\", \"segment\": \"rp\", \"hook\": \"cheap openai gateway\",\n         \"body\": \"saves money\", \"utm\": {\"source\": \"reddit\", \"content\": \"armB\"}},\n    ], ensure_ascii=False), encoding=\"utf-8\")\n    return CFG.Config(root)\n\n\n# ---- E1 metrics correctness ----\ndef e1():\n    evs = []\n    truth = {\"sent\": 4, \"delivered\": 3, \"click\": 2, \"conversion\": 1}\n    for _ in range(4):\n        evs.append(EV.make_event(\"c\", \"sent\", arm_id=\"a\", propensity_p=0.5, policy_version=\"v\"))\n    for _ in range(3):\n        evs.append(EV.make_event(\"c\", \"delivered\"))\n    for _ in range(2):\n        evs.append(EV.make_event(\"c\", \"click\"))\n    evs.append(EV.make_event(\"c\", \"conversion\"))\n    f = M.funnel(evs, dims=(\"channel\",))[(\"c\",)]\n    ok = (f[\"L1_sent\"] == 4 and f[\"L2_delivered\"] == 3 and f[\"L5_click\"] == 2\n          and f[\"L6_conversion\"] == 1 and abs(f[\"cr_conv\"] - 0.25) < 1e-9)\n    rec(\"E1\", \"metrics funnel counts/rates exact\", ok,\n        \"sent=%d click=%d conv=%d cr=%.3f\" % (f[\"L1_sent\"], f[\"L5_click\"], f[\"L6_conversion\"], f[\"cr_conv\"]))\n\n\n# ---- E2 bandit convergence ----\ndef e2():\n    rng = random.Random(7)\n    probs = {\"a0\": 0.3, \"a1\": 0.3, \"a2\": 0.7, \"a3\": 0.3}  # a2 best\n    b = B.Bandit(None, gamma=1.0, rng=rng)\n    sim = random.Random(11)\n    picks = []\n    for _ in range(500):\n        d = b.select(list(probs), samples_for_propensity=40)\n        arm = d[\"arm_id\"]\n        r = 1.0 if sim.random() < probs[arm] else 0.0\n        b.update(arm, r)\n        picks.append(arm)\n    last = picks[-100:]\n    frac_best = last.count(\"a2\") / 100.0\n    rec(\"E2\", \"bandit converges to true-best arm (>0.9)\", frac_best > 0.9, \"best-share=%.2f\" % frac_best)\n\n\n# ---- E3 non-stationary adaptation ----\ndef _run_drift(gamma):\n    \"\"\"Return b-share in the 120-round window RIGHT AFTER the optimum flips (recovery SPEED).\"\"\"\n    rng = random.Random(3)\n    sim = random.Random(5)\n    b = B.Bandit(None, gamma=gamma, rng=rng)\n    picks = []\n    for t in range(800):\n        if t < 400:\n            probs = {\"a\": 0.85, \"b\": 0.15}\n        else:\n            probs = {\"a\": 0.15, \"b\": 0.85}   # optimum flips to b at t=400\n        d = b.select([\"a\", \"b\"], samples_for_propensity=30)\n        arm = d[\"arm_id\"]\n        r = 1.0 if sim.random() < probs[arm] else 0.0\n        b.update(arm, r)\n        picks.append(arm)\n    return picks[400:520].count(\"b\") / 120.0   # how fast it re-finds b after drift\n\n\ndef e3():\n    disc = _run_drift(0.9)     # discounted TS re-finds b quickly\n    stat = _run_drift(1.0)     # stationary TS stays anchored to stale optimum\n    rec(\"E3\", \"discounted TS recovers from drift faster than stationary\",\n        disc > 0.5 and disc > stat, \"post-drift b-share: discounted=%.2f stationary=%.2f\" % (disc, stat))\n\n\n# ---- E4 throttle never exceeds + AIMD ----\ndef e4():\n    with tempfile.TemporaryDirectory() as t:\n        thr = TH.Throttle(Path(t) / \"s.json\", clock=lambda: 1000.0, rng=random.Random(1))\n        pol = {\"day_cap\": 5, \"min_gap_sec\": 0, \"backoff\": {\"factor\": 0.5, \"cooldown_h\": 24}}\n        oks = sum(1 for _ in range(12) if thr.allow(\"acct\", \"reddit\", \"post\", pol)[0])\n        cap_before = thr.state[thr._key(\"acct\", \"reddit\", \"post\")][\"cap\"]\n        thr.on_throttle_signal(\"acct\", \"reddit\", \"post\", pol)\n        cap_after = thr.state[thr._key(\"acct\", \"reddit\", \"post\")][\"cap\"]\n        in_cd = thr.allow(\"acct\", \"reddit\", \"post\", pol)\n        ok = (oks == 5 and abs(cap_after - cap_before * 0.5) < 1e-9 and in_cd[0] is False)\n        rec(\"E4\", \"token-bucket cap honored + 429 halves cap + cooldown\",\n            ok, \"allowed=%d cap %.1f->%.1f cooldown=%s\" % (oks, cap_before, cap_after, not in_cd[0]))\n\n\n# ---- E5 compliance fail-closed ----\ndef e5():\n    pol = {\"banned_claims\": [\"100% uncensored\"], \"physical_address\": \"1 Test St\"}\n    base = {\"transport\": \"smtp\", \"from_addr\": \"a@x.test\", \"subject\": \"Hello\",\n            \"unsubscribe\": \"https://x.test/u\", \"recipient\": \"u@x.test\", \"recipient_country\": \"US\",\n            \"physical_address\": \"1 Test St\"}\n    good = C.check(dict(base), policy=pol, suppression=set(), consent={})[0]\n    no_unsub = C.check({**base, \"unsubscribe\": \"\"}, policy=pol, suppression=set(), consent={})[0]\n    no_addr = C.check({**base, \"physical_address\": \"\", **{\"_\": 0}}, policy={\"banned_claims\": []},\n                      suppression=set(), consent={})[0]\n    eu = C.check({**base, \"recipient_country\": \"DE\"}, policy=pol, suppression=set(), consent={})[0]\n    supp = C.check(dict(base), policy=pol, suppression={\"u@x.test\"}, consent={})[0]\n    banned = C.check({**base, \"body\": \"we are 100% uncensored\"}, policy=pol, suppression=set(), consent={})[0]\n    ok = good and not no_unsub and not no_addr and not eu and not supp and not banned\n    rec(\"E5\", \"compliance gate fail-closed (all 5 violations rejected, valid passes)\", ok,\n        \"good=%s unsub=%s addr=%s eu=%s supp=%s banned=%s\" % (good, no_unsub, no_addr, eu, supp, banned))\n\n\n# ---- E6 attribution ----\ndef e6():\n    evs = [\n        EV.make_event(\"reddit\", \"sent\", arm_id=\"armA\", subject_key=\"u1\", utm={\"content\": \"armA\"},\n                      propensity_p=0.5, policy_version=\"v\"),\n        EV.make_event(\"reddit\", \"click\", arm_id=\"armA\", subject_key=\"u1\"),\n        EV.make_event(\"reddit\", \"conversion\", subject_key=\"u1\"),\n        EV.make_event(\"mastodon\", \"sent\", arm_id=\"armB\", subject_key=\"u2\", utm={\"content\": \"armB\"},\n                      propensity_p=0.5, policy_version=\"v\"),\n        EV.make_event(\"mastodon\", \"conversion\", subject_key=\"u2\"),\n    ]\n    res = {r[\"conversion_event\"]: r for r in M.attribute(evs)}\n    a = M.attribute(evs)\n    by_subj = {x[\"attributed_channel\"]: x for x in a}\n    ok = (len(a) == 2 and by_subj.get(\"reddit\", {}).get(\"attributed_arm\") == \"armA\"\n          and by_subj.get(\"mastodon\", {}).get(\"attributed_arm\") == \"armB\")\n    rec(\"E6\", \"last-non-direct attribution maps conversions to right (channel,arm)\", ok,\n        json.dumps([(x[\"attributed_channel\"], x[\"attributed_arm\"]) for x in a]))\n\n\n# ---- E7 dry-run engine + E8 propensity + E10 schema (shared run) ----\n@contextmanager\ndef _synthetic_private_metadata(root):\n    \"\"\"Scope the selftest's repository evidence to its temporary synthetic companion.\"\"\"\n    from scripts import private_storage\n    root = Path(root).resolve()\n    fixture = json.loads((_HERE.parent/'fixtures/promotion.json').read_text())\n\n    def repository(existing):\n        if not existing.is_relative_to(root):\n            raise ValueError('selftest attempted to leave its temporary companion')\n        return root\n\n    def metadata(argv):\n        if argv[0] == 'git':\n            if argv[-1:] == ['remote']:\n                return 'origin'\n            if argv[-3:] == ['rev-parse', '--verify', 'HEAD']:\n                return '1'*40\n            if (('get-url' in argv and '--all' in argv and argv[-1] == 'origin')\n                    or argv[-3:] == ['remote', 'get-url', 'origin']):\n                return 'https://github.com/example/synthetic-promotion-config.git'\n            raise AssertionError('unexpected Git metadata query')\n        if argv[0] == 'gh' and argv[1:4] == ['repo', 'view', 'example/synthetic-promotion-config']:\n            return '{\"visibility\":\"PRIVATE\",\"nameWithOwner\":\"example/synthetic-promotion-config\"}'\n        raise AssertionError('unexpected metadata operation')\n\n    with patch.object(private_storage, 'repository', repository), patch.object(private_storage, '_run', metadata):\n        yield\n\n\ndef e7_e8_e10():\n    with tempfile.TemporaryDirectory() as t, _synthetic_private_metadata(t):\n        cfg = _mk_config(t, send_mode=\"dry_run\")\n        env = {}  # no PROMO_LIVE_AUTHORIZED_* -> must simulate\n        res = ORCH.run_once(cfg, \"camp\", env=env, rng=random.Random(2))\n        evs = EV.read(cfg.metrics_dir() / \"events.jsonl\")\n        dry = cfg.metrics_dir() / \"dry-run.jsonl\"\n        types = [e[\"event_type\"] for e in evs]\n        no_live = all(not e.get(\"live\") for e in evs)\n        sim_ok = \"simulated\" in types and \"sent\" not in types and dry.is_file()\n        rec(\"E7\", \"dry-run: full pipeline, only simulated events, zero live egress\",\n            sim_ok and no_live and res[\"dispatch\"][\"status\"] == \"simulated\",\n            \"types=%s dryrun=%s\" % (types, dry.is_file()))\n        # E8 propensity completeness on decision events\n        dec = [e for e in evs if e.get(\"arm_id\") and e[\"event_type\"] in (\"sent\", \"simulated\")]\n        e8_ok = bool(dec) and all(e.get(\"propensity_p\") is not None and e.get(\"policy_version\") for e in dec)\n        rec(\"E8\", \"every decision event carries propensity_p + policy_version\", e8_ok,\n            \"decision_events=%d\" % len(dec))\n        # E10 schema gate\n        viol = sum(len(EV.validate_event(e)) for e in evs)\n        bad = EV.validate_event({\"channel\": None, \"event_type\": \"sent\"})  # should be flagged\n        rec(\"E10\", \"all events pass JSON schema; malformed is caught\", viol == 0 and len(bad) > 0,\n            \"violations=%d malformed_flags=%d\" % (viol, len(bad)))\n\n\n# ---- E9 anti-fingerprint ----\ndef e9():\n    tmpl = (\"{Hey|Hi|Yo|Sup}, {tried|been running|switched to|found} {this|a|some} \"\n            \"{free|cheap|budget|low-cost} {proxy|gateway|relay|endpoint} for \"\n            \"{roleplay|chatbots|creative writing|companions} \u2014 \"\n            \"{rock solid|zero downtime|super stable|never drops} {so far|lately|this month}\"\n            \"{.|!|, honestly|, ngl}\")\n    vs = FP.variants(tmpl, 5, seed=4)\n    mx = FP.max_pairwise_similarity(vs)\n    hashes = len({FP.content_hash(v) for v in vs})\n    rec(\"E9\", \"multi-account variants stay distinct (pairwise sim <0.7, unique hashes)\",\n        mx < 0.7 and hashes == len(vs), \"max_sim=%.2f unique=%d/%d\" % (mx, hashes, len(vs)))\n\n\n# ---- E11 delayed-conversion censoring ----\ndef e11():\n    now = 100000.0\n    inside = [EV.make_event(\"c\", \"sent\", arm_id=\"z\", ts=now - 100, propensity_p=0.5, policy_version=\"v\")]\n    r1, s1 = M.reward_for_arm(inside, \"z\", conversion_window_s=1000, now=now)\n    outside = [EV.make_event(\"c\", \"sent\", arm_id=\"z\", ts=now - 5000, propensity_p=0.5, policy_version=\"v\")]\n    r2, s2 = M.reward_for_arm(outside, \"z\", conversion_window_s=1000, now=now)\n    ok = (s1 == \"censored\" and r1 is None and s2 == \"ok\" and r2 is not None)\n    rec(\"E11\", \"delayed conversion inside window = censored (not negative)\", ok,\n        \"inside=%s outside=%s\" % (s1, s2))\n\n\n# ---- E12 idempotency via schedule-reminder base ----\ndef e12():\n    br = ScheduleBridge()\n    if not br.available():\n        rec(\"E12\", \"idempotent schedule writes (replay = no dup)\", None,\n            \"GAP: schedule-reminder base not installed\")\n        return\n    with tempfile.TemporaryDirectory() as t:\n        db = str(Path(t) / \"r.db\")\n        b = ScheduleBridge(db_path=db)\n        b.init()\n        key = \"promotion:test:armA:20260625\"\n        r1 = b.schedule_item(title=\"t\", due_at=\"2026-07-01T10:00:00Z\", idempotency_key=key,\n                             ext={\"x_promotion_arm_id\": \"armA\"})\n        r2 = b.schedule_item(title=\"t\", due_at=\"2026-07-01T10:00:00Z\", idempotency_key=key,\n                             ext={\"x_promotion_arm_id\": \"armA\"})\n        lst = b.list_active()\n        items = lst.get(\"items\", lst.get(\"results\", []))\n        n = len(items) if isinstance(items, list) else None\n        id1 = (r1.get(\"item\") or r1).get(\"id\") if isinstance(r1, dict) else None\n        id2 = (r2.get(\"item\") or r2).get(\"id\") if isinstance(r2, dict) else None\n        ok = (n == 1) or (id1 is not None and id1 == id2)\n        rec(\"E12\", \"idempotent schedule writes (replay = no dup)\", ok,\n            \"items=%s id1=%s id2=%s\" % (n, id1, id2))\n\n\ndef main():\n    e1(); e2(); e3(); e4(); e5(); e6(); e7_e8_e10(); e9(); e11(); e12()\n    print(\"promotion-assistant acceptance gate (E1-E12)\")\n    print(\"-\" * 70)\n    fails = 0\n    gaps = 0\n    for i, name, ok, detail in R:\n        if ok is None:\n            tag = \"GAP \"\n            gaps += 1\n        elif ok:\n            tag = \"PASS\"\n        else:\n            tag = \"FAIL\"\n            fails += 1\n        print(\"  [%s] %-4s %s\" % (tag, i, name))\n        if detail and (ok is not True):\n            print(\"           -> %s\" % detail)\n    print(\"-\" * 70)\n    print(\"%d checks | %d pass | %d fail | %d gap\" %\n          (len(R), sum(1 for _, _, o, _ in R if o is True), fails, gaps))\n    return 1 if fails else 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
    "tests/fixtures/sample_events.jsonl": "{\"schema\": \"promo.event.v1\", \"channel\": \"reddit-rp\", \"event_type\": \"simulated\", \"arm_id\": \"armA\", \"propensity_p\": 0.5, \"policy_version\": \"v1\"}\n{\"schema\": \"promo.event.v1\", \"channel\": \"reddit-rp\", \"event_type\": \"click\", \"subject_key\": \"u1\"}\n",
    "tests/test_promotion_v5.py": "\"\"\"Generated synthetic regressions for Promotion5; no live effects are used.\"\"\"\nimport importlib.util\nimport io\nimport json\nfrom pathlib import Path\nimport sys\nfrom types import SimpleNamespace\nimport urllib.error\nimport urllib.request\n\nimport pytest\n\nfrom scripts import cli, config, events, orchestrate, participation, runs\nfrom test_owned_identity import owned\nfrom test_review_runs import case\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef test_cli_conversion_window_uses_production_clock_and_preserves_event_policy(\n        case, monkeypatch, capsys):\n    now = [2000000000.0]\n    monkeypatch.setattr(runs.time, \"time\", lambda: now[0])\n    monkeypatch.setattr(cli, \"_load\", lambda args: case[\"cfg\"])\n    args = [\"run\", \"--campaign\", case[\"campaign\"], \"--once\",\n            \"--conversion-window-days\", \"1\", \"--run-id\", case[\"run_id\"]]\n    assert cli.main(args) == 0\n    first = json.loads(capsys.readouterr().out)\n    assert first[\"status\"] == \"simulated\" and first[\"reward_status\"] == \"censored\"\n    assert first[\"reward\"] is None\n    state_path = case[\"root\"] / \"metrics/bandit-state.json\"\n    state = json.loads(state_path.read_text())\n    assert len(state[\"observation_credits\"]) == len(first[\"items\"]) > 0\n    assert all(credit[\"status\"] == \"censored\" for credit in state[\"observation_credits\"].values())\n    assert all(arm[\"alpha\"] == arm[\"beta\"] == 1.0 for arm in state[\"arms\"].values())\n    before = state_path.read_bytes()\n    now[0] += 2 * 86400\n    assert cli.main(args + [\"--resume\"]) == 0\n    resumed = json.loads(capsys.readouterr().out)\n    assert resumed[\"reward_status\"] == \"no-new-observations\"\n    assert state_path.read_bytes() == before\n\n\ndef test_injected_learning_clock_still_overrides_production_time(case, monkeypatch):\n    monkeypatch.setattr(events, \"now_ts\", lambda: 1000.0)\n    monkeypatch.setattr(runs.time, \"time\", lambda: 1000000.0)\n    result = orchestrate.run_once(case[\"cfg\"], case[\"campaign\"], env={},\n                                 clock=lambda: 1050.0, conversion_window_s=100)\n    assert result[\"reward\"] is None and result[\"reward_status\"] == \"censored\"\n\n\ndef test_identity_preflight_429_retains_not_applied_and_persists_cooldown(\n        owned, case, monkeypatch):\n    now = [2000000000.0]\n    requests = []\n    def limited(request, **kwargs):\n        requests.append(request.full_url)\n        assert request.full_url.endswith((\"createSession\", \"verify_credentials\"))\n        raise urllib.error.HTTPError(request.full_url, 429, \"Synthetic rate limit\", {},\n                                     io.BytesIO(b\"Synthetic response\"))\n    monkeypatch.setattr(urllib.request, \"urlopen\", limited)\n    first = owned[\"run\"](clock=lambda: now[0])\n    assert first[\"status\"] == \"failed\" and len(requests) == 1\n    item = owned[\"saved\"]()[\"items\"][0]\n    assert item[\"safe_to_retry\"] is True\n    assert item[\"receipt\"][\"status\"] == \"not_applied\" and item[\"receipt\"][\"rate_limited\"] is True\n    assert item[\"receipt\"][\"code\"] == 429 and \"No publish request\" in item[\"receipt\"][\"evidence\"]\n    throttle_path = case[\"root\"] / \"metrics/throttle-state.json\"\n    persisted = json.loads(throttle_path.read_text())\n    assert persisted[\"cooldowns\"] and min(persisted[\"cooldowns\"].values()) > now[0]\n    before = throttle_path.read_bytes()\n    assert owned[\"run\"](resume=True, clock=lambda: now[0])[\"status\"] == \"deferred\"\n    assert len(requests) == 1 and throttle_path.read_bytes() == before\n    platform = owned[\"platform\"]\n    fresh = orchestrate.run_once(\n        config.Config(case[\"root\"]), case[\"campaign\"], run_id=\"synthetic-next-run\",\n        env={\"PROMO_LIVE_AUTHORIZED_\" + platform.upper(): \"synthetic-token\"}, clock=lambda: now[0])\n    assert fresh[\"status\"] == \"deferred\" and len(requests) == 1\n    now[0] = max(persisted[\"cooldowns\"].values()) + 1\n    assert owned[\"run\"](resume=True, clock=lambda: now[0])[\"status\"] == \"failed\"\n    assert len(requests) == 2 and owned[\"posts\"] == []\n\n\n@pytest.mark.parametrize(\"base\", [\"https://example.com/item\", \"https://news.ycombinator.com/item\"])\ndef test_functional_query_ids_survive_manual_recording_and_tracking_deduplication(case, base):\n    args = {\"channel\": \"synthetic-manual\", \"arm_id\": \"synthetic-arm\", \"campaign\": \"synthetic-campaign\"}\n    first = orchestrate.record_post(case[\"cfg\"], url=base + \"?id=10001\", **args)\n    second = orchestrate.record_post(case[\"cfg\"], url=base + \"?id=10002\", **args)\n    repeated = orchestrate.record_post(\n        case[\"cfg\"], url=base + \"?utm_source=synthetic&id=10001&utm_medium=example#fragment\", **args)\n    assert first[\"status\"] == second[\"status\"] == repeated[\"status\"] == \"recorded\"\n    assert first[\"event_id\"] != second[\"event_id\"]\n    assert repeated[\"event_id\"] == first[\"event_id\"]\n    assert first[\"url\"] == base + \"?id=10001\" and second[\"url\"] == base + \"?id=10002\"\n    rows = events.read(case[\"root\"] / \"metrics/events.jsonl\")\n    assert len(rows) == 2 and len({row[\"decision_id\"] for row in rows}) == 2\n    assert {row[\"post_url\"] for row in rows} == {first[\"url\"], second[\"url\"]}\n\n\n@pytest.mark.parametrize(\"query\", [\"id=10001&id=10002\", \"id=&mode=full\", \"key=a%2Fb+z&sig=abc%3D\"])\ndef test_unknown_query_fields_are_preserved_verbatim(query):\n    base = \"https://example.com/item?\"\n    assert participation.canonical_permalink(base + query + \"&utm_source=synthetic\") == base + query\n\n\ndef generator():\n    spec = importlib.util.spec_from_file_location(\"synthetic_promotion_fixture_generator\",\n                                                  ROOT / \"tools/make_fixtures.py\")\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\ndef test_fixture_export_reproduces_every_declared_fixture_and_check_detects_drift(\n        tmp_path, monkeypatch):\n    module = generator()\n    out = tmp_path / \"export\"\n    monkeypatch.setattr(sys, \"argv\", [\"make_fixtures.py\", \"--out\", str(out)])\n    module.main()\n    declared = json.loads((ROOT / \".dataclass.json\").read_text())[\"fixture\"]\n    expected = {}\n    for relative in declared:\n        content = (ROOT / relative).read_bytes()\n        name = Path(relative).name\n        assert name not in expected or expected[name] == content\n        expected[name] = content\n        assert (out / name).read_bytes() == content\n    assert {path.name for path in out.iterdir()} == set(expected)\n    assert len([name for name in expected if name.endswith(\".py\")]) >= 9\n    monkeypatch.setattr(sys, \"argv\", [\"make_fixtures.py\", \"--out\", str(out), \"--check\"])\n    module.main()\n    assert {path.name: path.read_bytes() for path in out.iterdir()} == expected\n    altered = out / \"test_promotion_v5.py\"\n    altered.write_text(\"# Synthetic damaged export\\n\", encoding=\"utf-8\")\n    with pytest.raises(SystemExit, match=\"generated synthetic output mismatch\"):\n        module.main()\n\n\ndef test_fixture_export_rejects_conflicting_basename_before_writing(tmp_path, monkeypatch):\n    module = generator()\n    monkeypatch.setitem(module.TEXT_OUTPUTS, \"synthetic/promotion.json\", \"Synthetic collision\")\n    out = tmp_path / \"export\"\n    monkeypatch.setattr(sys, \"argv\", [\"make_fixtures.py\", \"--out\", str(out)])\n    with pytest.raises(ValueError, match=\"basename collision\"):\n        module.main()\n    assert not out.exists()\n\n\n@pytest.mark.parametrize(\"url\", [None, \"\", \"http://example.com/source\", \"https://user1@example.com/source\",\n                                 \"https://www.reddit.com/r/synthetic/\", \"not-a-url\"])\ndef test_draft_refuses_invalid_source_before_model_or_event(case, monkeypatch, capsys, url):\n    monkeypatch.setattr(cli, \"_load\", lambda args: case[\"cfg\"])\n    calls = []\n    def model(*args, **kwargs):\n        calls.append(args)\n        pytest.fail(\"invalid source reached model\")\n    monkeypatch.setitem(sys.modules, \"llmcall\", SimpleNamespace(call=model))\n    args = [\"participate\", \"draft\", \"--title\", \"Synthetic question\", \"--body\", \"Synthetic context\"]\n    if url is not None:\n        args += [\"--url\", url]\n    assert cli.main(args) == 2\n    assert calls == [] and \"invalid draft source --url\" in capsys.readouterr().err\n    assert not (case[\"root\"] / \"metrics/events.jsonl\").exists()\n\n\n@pytest.mark.parametrize(\"use_draft\", [False, True])\ndef test_documented_participation_source_and_record_contract(case, monkeypatch, capsys, use_draft):\n    monkeypatch.setattr(cli, \"_load\", lambda args: case[\"cfg\"])\n    calls = []\n    def model(prompt, **kwargs):\n        calls.append((prompt, kwargs))\n        return SimpleNamespace(text=\"Synthetic reply for human review.\")\n    monkeypatch.setitem(sys.modules, \"llmcall\", SimpleNamespace(call=model))\n    thread = \"https://www.reddit.com/r/synthetic/comments/abc/topic\"\n    args = [\"participate\", \"record\", \"--url\", thread + \"/xyz\",\n            \"--thread\", thread, \"--type\", \"give\"]\n    if use_draft:\n        assert cli.main([\"participate\", \"draft\", \"--url\", thread,\n                         \"--title\", \"Synthetic question\", \"--body\", \"Synthetic context\"]) == 0\n        draft = events.read(case[\"root\"] / \"metrics/events.jsonl\")[0]\n        assert draft[\"thread\"] == participation.thread_identity(thread)\n        assert calls[0][1] == {\"mode\": \"agent\"}\n        args += [\"--draft-id\", draft[\"event_id\"]]\n        capsys.readouterr()\n    assert cli.main(args) == 0\n    record = json.loads(capsys.readouterr().out)\n    assert record[\"status\"] == \"recorded\" and record[\"participation_type\"] == \"give\"\n    assert bool(record[\"linked_draft\"]) is use_draft\n    skill = (ROOT / \"skills/promotion-assistant/SKILL.md\").read_text(encoding=\"utf-8\")\n    draft_line = next(line for line in skill.splitlines() if line.startswith(\"python scripts/cli.py participate draft \"))\n    record_line = next(line for line in skill.splitlines() if line.startswith(\"python scripts/cli.py participate record \"))\n    assert \"--url <source-thread>\" in draft_line\n    assert all(flag in record_line for flag in (\"--url\", \"--thread\", \"--type\"))\n    assert \"[--draft-id <draft-id>]\" in record_line\n",
    'tests/test_promotion_v6.py': '"""Generated synthetic controls for host binding, hot quotas and listing decisions."""\nfrom concurrent.futures import ThreadPoolExecutor\nimport json\nfrom types import SimpleNamespace\n\nimport pytest\n\nfrom scripts import cli, growth, participation, private_storage, throttle\n\n# Capture the real boundary before the autouse metadata fixture replaces it.\n_REAL_PRIVATE_RUN = private_storage._run\n\n\n@pytest.mark.parametrize("url", [\n    "https://github.com/example/synthetic-promotion-config.git",\n    "git@github.com:example/synthetic-promotion-config.git",\n    "ssh://git@github.com/example/synthetic-promotion-config.git",\n])\n@pytest.mark.parametrize("selected_host", [None, "github.com", "github.example.invalid"])\n@pytest.mark.parametrize("visibility", ["PUBLIC", "PRIVATE"])\ndef test_visibility_subprocess_is_bound_to_publication_host(\n        tmp_path, monkeypatch, url, selected_host, visibility):\n    identity = "example/synthetic-promotion-config"\n    qualified = "https://github.com/" + identity\n    if selected_host is None:\n        monkeypatch.delenv("GH_HOST", raising=False)\n    else:\n        monkeypatch.setenv("GH_HOST", selected_host)\n    monkeypatch.setenv("GIT_CONFIG_COUNT", "5")\n    calls = []\n\n    def git_metadata(repo, *args):\n        if args == ("remote",):\n            return "origin"\n        assert args[:2] == ("remote", "get-url") and args[-2:] == ("--all", "origin")\n        return url\n\n    def external(argv, **options):\n        calls.append((list(argv), options))\n        # A different host has a same-name PRIVATE repository. Only the\n        # qualified publication-host query may use the real endpoint verdict.\n        answer = visibility if argv[3] == qualified else "PRIVATE"\n        return SimpleNamespace(returncode=0, stdout=json.dumps(\n            {"visibility": answer, "nameWithOwner": identity}))\n\n    monkeypatch.setattr(private_storage, "_git", git_metadata)\n    monkeypatch.setattr(private_storage, "_run", _REAL_PRIVATE_RUN)\n    monkeypatch.setattr(private_storage.subprocess, "run", external)\n    if visibility == "PRIVATE":\n        accepted = private_storage.publication_destinations(tmp_path)\n        assert accepted == (("origin", "fetch", identity), ("origin", "push", identity))\n    else:\n        with pytest.raises(ValueError, match="PUBLIC or unknown"):\n            private_storage.publication_destinations(tmp_path)\n    assert calls\n    assert all(argv[:4] == ["gh", "repo", "view", qualified] for argv, _ in calls)\n    assert all(options["env"]["GH_HOST"] == "github.com" for _, options in calls)\n    assert all("GIT_CONFIG_COUNT" not in options["env"] for _, options in calls)\n    assert all(options["env"]["GIT_OPTIONAL_LOCKS"] == "0" for _, options in calls)\n\n\ndef instance(path, now):\n    return throttle.Throttle(path, clock=lambda: now[0])\n\n\ndef reserve(controller, identity, cap):\n    return controller.reserve(\n        "synthetic-account", "discord", "post",\n        {"day_cap": cap, "min_gap_sec": 0},\n        reservation_id=identity, payload={"body": "Acme synthetic announcement"})\n\n\ndef saved_bucket(path):\n    document = json.loads(path.read_text())\n    assert len(document["buckets"]) == 1\n    return next(iter(document["buckets"].values()))\n\n\n@pytest.mark.parametrize("restart", [False, True])\n@pytest.mark.parametrize("retry", [False, True])\n@pytest.mark.parametrize("rollover", [False, True])\ndef test_zero_policy_blocks_existing_bucket_and_old_reservations(\n        tmp_path, restart, retry, rollover):\n    now = [1000.0]\n    path = tmp_path / "state.json"\n    controller = instance(path, now)\n    assert reserve(controller, "synthetic-initial", 50)[0]\n    now[0] += 86400 if rollover else 1\n    if restart:\n        controller = instance(path, now)\n    result = reserve(controller, "synthetic-initial" if retry else "synthetic-new", 0)\n    assert result[0] is False and "daily cap" in result[1]\n    bucket = saved_bucket(path)\n    assert bucket["base_cap"] == 0 and bucket["tokens"] == 0\n    assert len(json.loads(path.read_text())["reservations"]) == 1\n\n\n@pytest.mark.parametrize("spent", [0, 1, 3, 7])\n@pytest.mark.parametrize("restart", [False, True])\ndef test_reduced_limit_preserves_consumed_quota(tmp_path, spent, restart):\n    now = [1000.0]\n    path = tmp_path / "state.json"\n    controller = instance(path, now)\n    controller._bucket("synthetic-account", "discord", "post", {"day_cap": 10})\n    controller.save()\n    for index in range(spent):\n        assert reserve(controller, "synthetic-before-%d" % index, 10)[0]\n    previous_period = saved_bucket(path)["last_refill"]\n    now[0] += 1\n    if restart:\n        controller = instance(path, now)\n    outcomes = [reserve(controller, "synthetic-after-%d" % index, 3)[0] for index in range(4)]\n    assert sum(outcomes) == max(0, 3-spent)\n    bucket = saved_bucket(path)\n    assert bucket["period_used"] == max(spent, 3)\n    assert bucket["last_refill"] == previous_period\n    assert bucket["base_cap"] == 3 and bucket["tokens"] == 0\n\n\ndef test_limit_changes_never_reset_usage_or_mint_midperiod_tokens(tmp_path):\n    now = [1000.0]\n    path = tmp_path / "state.json"\n    controller = instance(path, now)\n    for index in range(7):\n        assert reserve(controller, "synthetic-before-%d" % index, 10)[0]\n    for cap in (5, 0, 9):\n        controller = instance(path, now)\n        assert reserve(controller, "synthetic-after-%d" % cap, cap)[0] is False\n        assert saved_bucket(path)["period_used"] == 7\n        assert saved_bucket(path)["last_refill"] == 1000\n    now[0] += 86400\n    controller = instance(path, now)\n    assert sum(reserve(controller, "synthetic-next-%d" % index, 9)[0]\n               for index in range(10)) == 9\n    assert saved_bucket(path)["period_used"] == 9\n\n\ndef test_policy_reduction_preserves_aimd_capacity_and_consumption(tmp_path):\n    now = [1000.0]\n    path = tmp_path / "state.json"\n    controller = instance(path, now)\n    for index in range(2):\n        assert reserve(controller, "synthetic-before-%d" % index, 20)[0]\n    controller.record_throttle_signal(\n        "synthetic-account", "discord", "post",\n        {"day_cap": 20, "backoff": {"factor": 0.25, "cooldown_h": 1}})\n    now[0] += 3601\n    controller = instance(path, now)\n    assert sum(reserve(controller, "synthetic-after-%d" % index, 8)[0]\n               for index in range(4)) == 3\n    bucket = saved_bucket(path)\n    assert bucket["cap"] == 5 and bucket["base_cap"] == 8\n    assert bucket["period_used"] == 5 and bucket["tokens"] == 0\n    now[0] = 87400\n    controller = instance(path, now)\n    assert sum(reserve(controller, "synthetic-refill-%d" % index, 8)[0]\n               for index in range(6)) == 5\n\n\ndef test_concurrent_reservations_share_the_reduced_current_limit(tmp_path):\n    now = [1000.0]\n    path = tmp_path / "state.json"\n    controller = instance(path, now)\n    for index in range(2):\n        assert reserve(controller, "synthetic-initial-%d" % index, 50)[0]\n    controllers = [instance(path, now), instance(path, now)]\n    with ThreadPoolExecutor(max_workers=2) as pool:\n        futures = [pool.submit(reserve, item, "synthetic-race-%d" % index, 3)\n                   for index, item in enumerate(controllers)]\n        outcomes = [future.result()[0] for future in futures]\n    assert sum(outcomes) == 1\n    bucket = saved_bucket(path)\n    assert bucket["period_used"] == 3 and bucket["tokens"] == 0\n    assert len(json.loads(path.read_text())["reservations"]) == 3\n\n\n@pytest.mark.parametrize("cap", [-1, float("nan"), float("inf")])\ndef test_invalid_policy_is_checked_for_existing_buckets(tmp_path, cap):\n    now = [1000.0]\n    path = tmp_path / "state.json"\n    controller = instance(path, now)\n    assert reserve(controller, "synthetic-initial", 10)[0]\n    before = path.read_bytes()\n    with pytest.raises(ValueError, match="day_cap"):\n        reserve(instance(path, now), "synthetic-new", cap)\n    assert path.read_bytes() == before\n\n\n@pytest.mark.parametrize("learned,base,remaining", [(5, 20, 4), (15, 10, 7)])\ndef test_legacy_aimd_bucket_waits_for_normal_refill(tmp_path, learned, base, remaining):\n    now = [1000.0]\n    path = tmp_path / "state.json"\n    assert reserve(instance(path, now), "synthetic-initial", base)[0]\n    document = json.loads(path.read_text())\n    bucket = next(iter(document["buckets"].values()))\n    bucket.pop("period_used")\n    bucket.update(cap=learned, base_cap=base, tokens=learned)\n    path.write_text(json.dumps(document))\n    for identity in ("synthetic-current", "synthetic-initial"):\n        assert reserve(instance(path, now), identity, 8)[0] is False\n    bucket = saved_bucket(path)\n    assert bucket["usage_known"] is False and bucket["tokens"] == 0\n    assert bucket["last_refill"] == 1000 and bucket["cap"] == learned\n    now[0] += 86400\n    assert reserve(instance(path, now), "synthetic-next", 8)[0]\n    bucket = saved_bucket(path)\n    assert bucket["usage_known"] is True\n    assert bucket["period_used"] == 1 and bucket["tokens"] == remaining\n\n\n@pytest.mark.parametrize("usage", [-1, float("nan"), float("inf"), "synthetic-invalid"])\ndef test_malformed_durable_usage_is_rejected_without_rewrite(tmp_path, usage):\n    now = [1000.0]\n    path = tmp_path / "state.json"\n    assert reserve(instance(path, now), "synthetic-initial", 10)[0]\n    document = json.loads(path.read_text())\n    next(iter(document["buckets"].values()))["period_used"] = usage\n    path.write_text(json.dumps(document))\n    before = path.read_bytes()\n    with pytest.raises(ValueError, match="period usage"):\n        instance(path, now)\n    assert path.read_bytes() == before\n\n\ndef config(banned):\n    return SimpleNamespace(\n        product={"product": "AcmeCorp", "value_props": ["Documented usage limits"]},\n        banned_claims=banned)\n\n\n@pytest.mark.parametrize("claim", ["free model", "acmecorp", "compatible"])\ndef test_rejected_listing_never_becomes_submission_copy(monkeypatch, capsys, claim):\n    cfg = config([claim])\n    result = growth.listing(cfg)\n    assert result["status"] == "blocked" and result["description"] is None\n    assert result["reasons"] and any(claim in reason.lower() for reason in result["reasons"])\n    monkeypatch.setattr(cli, "_load", lambda args: cfg)\n    assert cli.cmd_growth(SimpleNamespace(what="listing")) == 1\n    rendered = capsys.readouterr().out\n    assert "Listing blocked:" in rendered\n    assert "Description:" not in rendered and "Submit at:" not in rendered\n\n\ndef test_safe_listing_remains_available_to_library_and_cli(monkeypatch, capsys):\n    cfg = config([])\n    result = growth.listing(cfg)\n    assert result["status"] == "ready" and result["reasons"] == []\n    assert "AcmeCorp" in result["description"] and result["directories"]\n    monkeypatch.setattr(cli, "_load", lambda args: cfg)\n    assert cli.cmd_growth(SimpleNamespace(what="listing")) == 0\n    rendered = capsys.readouterr().out\n    assert result["description"] in rendered and "Submit at:" in rendered\n\n\n@pytest.mark.parametrize("gives,asks,holds,next_ok", [\n    (0, 0, True, False),\n    (8, 0, True, False),\n    (9, 0, True, True),\n    (9, 1, True, False),\n    (17, 1, True, False),\n    (18, 1, True, True),\n    (18, 2, True, False),\n    (27, 2, True, True),\n    (8, 1, False, False),\n])\ndef test_next_ask_flag_accounts_for_the_prospective_ask(gives, asks, holds, next_ok):\n    ledger = [{"type": "give"} for _ in range(gives)] + [{"type": "ask"} for _ in range(asks)]\n    result = participation.ledger_balance(ledger)\n    assert result["gives"] == gives and result["asks"] == asks\n    assert result["holds_9to1"] is holds\n    assert result["next_ask_ok"] is next_ok\n',
}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--out', type=Path, help='export every declared synthetic fixture by basename')
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    root = args.out if args.out else ROOT
    outputs = {name: body.encode('utf-8') for name, body in TEXT_OUTPUTS.items()}
    outputs['tests/fixtures/promotion.json'] = render()
    outputs['skills/promotion-assistant/fixtures/promotion.json'] = render()
    if args.out:
        flattened = {}
        for relative, content in outputs.items():
            name = Path(relative).name
            if name in flattened and flattened[name] != content:
                raise ValueError('generated fixture basename collision: '+name)
            flattened[name] = content
        outputs = flattened
    for relative, content in sorted(outputs.items()):
        path = root/relative
        if args.check:
            if not path.is_file() or path.read_bytes() != content:
                raise SystemExit('generated synthetic output mismatch: '+relative)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(content)


if __name__ == '__main__':
    main()
